import { useParams, useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import { Skeleton } from '../components/Skeleton';
import {
  formatCurrency, formatDateFull, formatDateShort, getDueDateLabel,
  URGENCY_CSS_CLASS, URGENCY_LABELS, calcInterestPaid,
} from '../lib/utils';
import {
  ArrowLeft, Copy, CheckCircle, Pencil,
  Paperclip, Calendar, AlertTriangle, Clock, CheckCircle2,
  Upload, FileText, Image, ExternalLink, Trash2, RotateCcw, Tag, Truck,
} from 'lucide-react';
import type { BillView, Attachment } from '../types/database';
import { useState, useRef } from 'react';

const KIND_LABELS: Record<string, string> = {
  boleto: 'Boleto',
  receipt: 'Comprovante',
  invoice: 'Nota fiscal',
  other: 'Outro',
};

function useBillDetail(billId: string | undefined, orgId: string | undefined) {
  return useQuery({
    queryKey: ['bill', billId],
    queryFn: async () => {
      if (!billId || !orgId) return null;
      const { data, error } = await supabase
        .from('bills_view')
        .select('*')
        .eq('id', billId)
        .eq('org_id', orgId)
        .single();
      if (error) throw error;
      return data as BillView;
    },
    enabled: !!billId && !!orgId,
  });
}

function useAttachments(billId: string | undefined, orgId: string | undefined) {
  return useQuery({
    queryKey: ['attachments', billId],
    queryFn: async () => {
      if (!billId || !orgId) return [];
      const { data, error } = await supabase
        .from('attachments')
        .select('*')
        .eq('bill_id', billId)
        .eq('org_id', orgId)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return (data ?? []) as Attachment[];
    },
    enabled: !!billId && !!orgId,
  });
}

export default function BillDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { currentOrg } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [showPayModal, setShowPayModal] = useState(false);
  const [payDate, setPayDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [payAmount, setPayAmount] = useState('');
  const [uploadKind, setUploadKind] = useState<'boleto' | 'receipt' | 'invoice' | 'other'>('receipt');
  const [uploading, setUploading] = useState(false);

  const { data: bill, isLoading } = useBillDetail(id, currentOrg?.org_id);
  const { data: attachments = [], isLoading: loadingAttachments } = useAttachments(id, currentOrg?.org_id);

  const markPaidMutation = useMutation({
    mutationFn: async ({ date, amount }: { date: string; amount: number }) => {
      if (!id) throw new Error('Boleto inválido');
      const { error } = await supabase
        .from('bills')
        .update({ status: 'paid', paid_at: date, paid_amount: amount })
        .eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bill', id] });
      queryClient.invalidateQueries({ queryKey: ['bills'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      toast('Boleto marcado como pago!', 'success');
      setShowPayModal(false);
    },
    onError: () => toast('Erro ao marcar como pago.', 'error'),
  });

  const undoPaymentMutation = useMutation({
    mutationFn: async () => {
      if (!id) throw new Error();
      const { error } = await supabase
        .from('bills')
        .update({ status: 'pending', paid_at: null, paid_amount: null })
        .eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bill', id] });
      queryClient.invalidateQueries({ queryKey: ['bills'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      toast('Pagamento desfeito.', 'success');
    },
    onError: () => toast('Erro ao desfazer pagamento.', 'error'),
  });

  const deleteAttachmentMutation = useMutation({
    mutationFn: async (att: Attachment) => {
      await supabase.storage.from('documents').remove([att.storage_path]);
      const { error } = await supabase.from('attachments').delete().eq('id', att.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['attachments', id] });
      toast('Anexo removido.', 'success');
    },
    onError: () => toast('Erro ao remover anexo.', 'error'),
  });

  async function copyBarcode() {
    if (!bill?.barcode_line) return;
    await navigator.clipboard.writeText(bill.barcode_line);
    toast('Código de barras copiado!', 'success');
  }

  async function handleMarkPaid() {
    const amount = parseFloat(payAmount.replace(',', '.')) || bill!.amount;
    markPaidMutation.mutate({ date: payDate, amount });
  }

  async function handleUpload(file: File) {
    if (!currentOrg?.org_id || !id) return;
    setUploading(true);
    try {
      const ext = file.name.split('.').pop();
      const path = `${currentOrg.org_id}/${id}/${Date.now()}.${ext}`;
      const { error: uploadError } = await supabase.storage
        .from('documents')
        .upload(path, file, { contentType: file.type });
      if (uploadError) throw uploadError;

      const { error: dbError } = await supabase.from('attachments').insert({
        org_id: currentOrg.org_id,
        bill_id: id,
        kind: uploadKind,
        storage_path: path,
        file_name: file.name,
        mime: file.type,
        size_bytes: file.size,
      });
      if (dbError) throw dbError;

      queryClient.invalidateQueries({ queryKey: ['attachments', id] });
      toast('Arquivo anexado!', 'success');
    } catch {
      toast('Erro ao fazer upload do arquivo.', 'error');
    } finally {
      setUploading(false);
    }
  }

  async function openAttachment(att: Attachment) {
    const { data } = await supabase.storage
      .from('documents')
      .createSignedUrl(att.storage_path, 300); // 5 min expiry
    if (data?.signedUrl) {
      window.open(data.signedUrl, '_blank');
    } else {
      toast('Erro ao abrir o arquivo.', 'error');
    }
  }

  function formatFileSize(bytes: number | null): string {
    if (!bytes) return '';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }

  if (isLoading) {
    return (
      <main className="page" id="page-bill-detail">
        <div className="page-content container">
          <Skeleton height={200} />
          <Skeleton height={60} />
          <Skeleton height={120} />
        </div>
      </main>
    );
  }

  if (!bill) {
    return (
      <main className="page">
        <div className="page-content container">
          <div className="empty-state">
            <AlertTriangle size={48} color="var(--urgent)" />
            <h2>Boleto não encontrado</h2>
            <button className="btn btn-secondary" onClick={() => navigate('/boletos')}>
              Voltar para boletos
            </button>
          </div>
        </div>
      </main>
    );
  }

  const urgency = bill.urgency;
  const dueDateLabel = getDueDateLabel(bill.due_date, bill.status);
  const interest = calcInterestPaid(bill.amount, bill.paid_amount);

  const UrgencyIcon = urgency === 'urgent' ? AlertTriangle : urgency === 'soon' ? Clock : CheckCircle2;
  const urgencyColor = urgency === 'urgent' ? 'var(--urgent)' : urgency === 'soon' ? 'var(--soon)' : urgency === 'ok' ? 'var(--ok)' : 'var(--paid)';

  return (
    <main className="page animate-fade-in" id="page-bill-detail">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Detalhe do boleto</h1>
          {bill.status !== 'canceled' && (
            <button className="btn-ghost btn-icon" onClick={() => navigate(`/boletos/${id}/editar`)} aria-label="Editar boleto"
              style={{ width: 40, height: 40, minHeight: 40 }}>
              <Pencil size={18} />
            </button>
          )}
        </div>
      </header>

      <div className="page-content container">
        {/* Main info card */}
        <section className="card" style={{ background: 'var(--surface)' }} aria-label="Informações do boleto">
          <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 'var(--space-4)' }}>
            <div>
              <h2 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 4 }}>
                {bill.beneficiary_name ?? bill.description ?? 'Boleto'}
              </h2>
              {bill.description && bill.beneficiary_name && (
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>{bill.description}</p>
              )}
            </div>
            <span className={`chip ${URGENCY_CSS_CLASS[urgency]}`} aria-label={`Urgência: ${URGENCY_LABELS[urgency]}`}>
              <UrgencyIcon size={12} aria-hidden="true" />
              {URGENCY_LABELS[urgency]}
            </span>
          </div>

          {/* Amount */}
          <p className="amount" style={{ fontSize: 'var(--text-2xl)', color: 'var(--brand)', marginBottom: 'var(--space-4)' }}>
            {formatCurrency(bill.amount)}
          </p>

          {/* Meta info */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
              <Calendar size={16} color="var(--text-muted)" aria-hidden="true" />
              <div>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Vencimento</p>
                <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: urgencyColor }}>
                  {formatDateFull(bill.due_date)} · {dueDateLabel}
                </p>
              </div>
            </div>

            {bill.supplier_name && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                <Truck size={16} color="var(--text-muted)" aria-hidden="true" />
                <div>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Fornecedor</p>
                  <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>{bill.supplier_name}</p>
                </div>
              </div>
            )}

            {bill.category_name && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                <Tag size={16} color="var(--text-muted)" aria-hidden="true" />
                <div>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Categoria</p>
                  <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>
                    {bill.category_icon} {bill.category_name}
                  </p>
                </div>
              </div>
            )}

            {bill.status === 'paid' && bill.paid_at && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                <CheckCircle size={16} color="var(--ok)" aria-hidden="true" />
                <div>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Pago em</p>
                  <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: 'var(--ok)' }}>
                    {formatDateShort(bill.paid_at)}
                    {bill.paid_amount && ` · ${formatCurrency(bill.paid_amount)}`}
                    {interest > 0 && (
                      <span style={{ color: 'var(--urgent)', marginLeft: 'var(--space-2)' }}>
                        (+{formatCurrency(interest)} juros)
                      </span>
                    )}
                  </p>
                </div>
              </div>
            )}
          </div>
        </section>

        {/* Barcode section */}
        {bill.barcode_line && (
          <section className="card" aria-label="Código de barras">
            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginBottom: 'var(--space-3)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>
              Código de barras
            </p>
            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', wordBreak: 'break-all', fontFamily: 'monospace', lineHeight: 1.6, marginBottom: 'var(--space-3)' }}>
              {bill.barcode_line}
            </p>
            <button
              id="btn-copy-barcode"
              className="btn btn-primary btn-full"
              onClick={copyBarcode}
              aria-label="Copiar código de barras"
            >
              <Copy size={18} aria-hidden="true" />
              Copiar código de barras
            </button>
          </section>
        )}

        {/* Attachments section */}
        <section className="card" aria-label="Anexos" aria-labelledby="attachments-heading">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-4)' }}>
            <p id="attachments-heading" style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>
              Anexos {attachments.length > 0 && `(${attachments.length})`}
            </p>
            <div style={{ display: 'flex', gap: 'var(--space-2)', alignItems: 'center' }}>
              <select
                className="input"
                style={{ fontSize: 'var(--text-xs)', padding: '4px 8px', height: 'auto' }}
                value={uploadKind}
                onChange={e => setUploadKind(e.target.value as typeof uploadKind)}
                aria-label="Tipo de anexo"
              >
                <option value="boleto">Boleto</option>
                <option value="receipt">Comprovante</option>
                <option value="invoice">Nota fiscal</option>
                <option value="other">Outro</option>
              </select>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,application/pdf"
                style={{ display: 'none' }}
                onChange={async e => {
                  const file = e.target.files?.[0];
                  if (file) await handleUpload(file);
                  e.target.value = '';
                }}
              />
              <button
                className="btn btn-secondary btn-sm"
                onClick={() => fileInputRef.current?.click()}
                disabled={uploading}
                aria-label="Adicionar anexo"
              >
                {uploading ? (
                  <span style={{ fontSize: 'var(--text-xs)' }}>Enviando...</span>
                ) : (
                  <>
                    <Upload size={14} aria-hidden="true" />
                    <span>Adicionar</span>
                  </>
                )}
              </button>
            </div>
          </div>

          {loadingAttachments ? (
            <div className="skeleton" style={{ height: 48, borderRadius: 'var(--radius-md)' }} />
          ) : attachments.length === 0 ? (
            <div style={{
              textAlign: 'center',
              padding: 'var(--space-5)',
              background: 'var(--surface-2)',
              borderRadius: 'var(--radius-md)',
              border: '1px dashed var(--border)',
            }}>
              <Paperclip size={24} color="var(--text-muted)" style={{ marginBottom: 8 }} />
              <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                Nenhum arquivo anexado ainda.
              </p>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', marginTop: 4 }}>
                Adicione o boleto original, comprovante de pagamento ou nota fiscal.
              </p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              {attachments.map(att => {
                const isImage = att.mime?.startsWith('image/');
                return (
                  <div
                    key={att.id}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 'var(--space-3)',
                      padding: 'var(--space-3)', background: 'var(--surface-2)',
                      borderRadius: 'var(--radius-md)', border: '1px solid var(--border)',
                    }}
                  >
                    <div style={{
                      width: 40, height: 40, borderRadius: 'var(--radius-md)',
                      background: 'var(--surface)', display: 'flex',
                      alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                    }}>
                      {isImage ? <Image size={20} color="var(--brand)" /> : <FileText size={20} color="var(--text-muted)" />}
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {att.file_name ?? att.storage_path.split('/').pop()}
                      </p>
                      <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                        {KIND_LABELS[att.kind]} · {formatFileSize(att.size_bytes)}
                      </p>
                    </div>
                    <button
                      className="btn-ghost btn-icon btn-sm"
                      onClick={() => openAttachment(att)}
                      aria-label="Abrir arquivo"
                    >
                      <ExternalLink size={16} />
                    </button>
                    <button
                      className="btn-ghost btn-icon btn-sm"
                      onClick={() => deleteAttachmentMutation.mutate(att)}
                      aria-label="Remover anexo"
                      style={{ color: 'var(--urgent)' }}
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                );
              })}
            </div>
          )}
        </section>

        {/* Actions */}
        {bill.status === 'pending' && (
          <button
            id="btn-mark-paid"
            className="btn btn-primary btn-full btn-lg"
            onClick={() => {
              setPayAmount(String(bill.amount));
              setShowPayModal(true);
            }}
          >
            <CheckCircle size={20} aria-hidden="true" />
            Marcar como pago
          </button>
        )}

        {bill.status === 'paid' && (
          <button
            id="btn-undo-payment"
            className="btn btn-secondary btn-full"
            onClick={() => undoPaymentMutation.mutate()}
            disabled={undoPaymentMutation.isPending}
          >
            <RotateCcw size={18} aria-hidden="true" />
            {undoPaymentMutation.isPending ? 'Desfazendo...' : 'Desfazer pagamento'}
          </button>
        )}
      </div>

      {/* Pay modal */}
      {showPayModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowPayModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="pay-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="pay-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              Marcar como pago
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div className="input-group">
                <label htmlFor="pay-date" className="input-label">Data do pagamento</label>
                <input
                  id="pay-date"
                  type="date"
                  className="input"
                  value={payDate}
                  onChange={e => setPayDate(e.target.value)}
                />
              </div>

              <div className="input-group">
                <label htmlFor="pay-amount" className="input-label">Valor pago (R$)</label>
                <input
                  id="pay-amount"
                  type="number"
                  step="0.01"
                  className="input amount"
                  value={payAmount}
                  onChange={e => setPayAmount(e.target.value)}
                />
                {parseFloat(payAmount) > bill.amount && (
                  <span style={{ fontSize: 'var(--text-xs)', color: 'var(--urgent)' }}>
                    Juros/multa: {formatCurrency(parseFloat(payAmount) - bill.amount)}
                  </span>
                )}
              </div>

              {/* Suggest adding receipt */}
              <div style={{
                padding: 'var(--space-3)',
                background: 'var(--surface-2)',
                borderRadius: 'var(--radius-md)',
                border: '1px solid var(--border)',
                fontSize: 'var(--text-xs)',
                color: 'var(--text-muted)',
              }}>
                💡 Após confirmar, você pode adicionar o comprovante na seção de Anexos.
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowPayModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-confirm-paid"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleMarkPaid}
                  disabled={markPaidMutation.isPending}
                >
                  {markPaidMutation.isPending ? 'Salvando...' : 'Confirmar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}
