import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Tag, Plus, Search, Pencil, Trash2,
  ArrowLeft, AlertCircle,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { Category } from '../types/database';

const PRESET_COLORS = [
  '#FFF21A', '#FF4D4D', '#FF9F1C', '#4ADE80',
  '#60A5FA', '#A78BFA', '#F472B6', '#34D399',
  '#FB923C', '#38BDF8',
];

const PRESET_ICONS = [
  '🏢', '🔧', '💡', '🚚', '📦', '💼', '🖨️', '💻',
  '🏪', '📱', '🛒', '🏦', '⚡', '🌐', '🎯',
];

function useCategories(orgId: string | undefined) {
  return useQuery({
    queryKey: ['categories', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .eq('org_id', orgId)
        .order('name');
      if (error) throw error;
      return (data ?? []) as Category[];
    },
    enabled: !!orgId,
  });
}

interface CategoryFormData {
  name: string;
  color: string;
  icon: string;
}

const emptyForm: CategoryFormData = { name: '', color: PRESET_COLORS[0], icon: PRESET_ICONS[0] };

export default function CategoriesPage() {
  const { currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Category | null>(null);
  const [form, setForm] = useState<CategoryFormData>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Category | null>(null);

  const { data: categories = [], isLoading } = useCategories(currentOrg?.org_id);

  const filtered = categories.filter(c =>
    c.name.toLowerCase().includes(search.toLowerCase())
  );

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setShowModal(true);
  }

  function openEdit(category: Category) {
    setEditing(category);
    setForm({ name: category.name, color: category.color ?? PRESET_COLORS[0], icon: category.icon ?? PRESET_ICONS[0] });
    setShowModal(true);
  }

  async function handleSave() {
    if (!currentOrg || !form.name.trim()) {
      toast('Informe o nome da categoria.', 'error');
      return;
    }
    setSaving(true);
    try {
      if (editing) {
        const { error } = await supabase
          .from('categories')
          .update({ name: form.name.trim(), color: form.color, icon: form.icon })
          .eq('id', editing.id);
        if (error) throw error;
        toast('Categoria atualizada!', 'success');
      } else {
        const { error } = await supabase
          .from('categories')
          .insert({ org_id: currentOrg.org_id, name: form.name.trim(), color: form.color, icon: form.icon });
        if (error) throw error;
        toast('Categoria criada!', 'success');
      }
      queryClient.invalidateQueries({ queryKey: ['categories'] });
      setShowModal(false);
    } catch {
      toast('Erro ao salvar categoria.', 'error');
    } finally {
      setSaving(false);
    }
  }

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from('categories').delete().eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['categories'] });
      toast('Categoria excluída.', 'success');
      setDeleteTarget(null);
    },
    onError: () => toast('Erro ao excluir. Verifique se há boletos vinculados.', 'error'),
  });

  return (
    <main className="page" id="page-categories">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Categorias</h1>
          <button className="btn btn-primary" onClick={openCreate} id="btn-new-category" aria-label="Nova categoria">
            <Plus size={18} strokeWidth={2.5} />
            <span className="desktop-only">Nova</span>
          </button>
        </div>
      </header>

      <div className="page-content container">
        <div className="search-wrapper">
          <Search size={18} className="search-icon" aria-hidden="true" />
          <input
            id="category-search"
            type="search"
            className="input search-input"
            placeholder="Buscar categoria..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            aria-label="Buscar categorias"
          />
        </div>

        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(4)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 64, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <Tag size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>{search ? 'Nenhum resultado' : 'Sem categorias'}</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              {search ? `Nenhuma categoria para "${search}".` : 'Organize seus gastos criando categorias.'}
            </p>
            {!search && (
              <button className="btn btn-primary" onClick={openCreate}>
                <Plus size={16} /> Criar categoria
              </button>
            )}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {filtered.map(category => (
              <div
                key={category.id}
                className="card"
                style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-4)' }}
              >
                <div style={{
                  width: 44, height: 44, borderRadius: 'var(--radius-md)',
                  background: category.color ? `${category.color}22` : 'var(--surface-2)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 22, flexShrink: 0,
                  border: category.color ? `2px solid ${category.color}44` : undefined,
                }}>
                  {category.icon ?? '🏷️'}
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>{category.name}</p>
                  {category.color && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 2 }}>
                      <div style={{ width: 10, height: 10, borderRadius: '50%', background: category.color }} />
                      <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{category.color}</p>
                    </div>
                  )}
                </div>
                <div style={{ display: 'flex', gap: 'var(--space-1)', flexShrink: 0 }}>
                  <button className="btn-ghost btn-icon btn-sm" onClick={() => openEdit(category)} aria-label={`Editar ${category.name}`}>
                    <Pencil size={16} />
                  </button>
                  <button
                    className="btn-ghost btn-icon btn-sm"
                    onClick={() => setDeleteTarget(category)}
                    aria-label={`Excluir ${category.name}`}
                    style={{ color: 'var(--urgent)' }}
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create/Edit Modal */}
      {showModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="cat-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="cat-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              {editing ? 'Editar categoria' : 'Nova categoria'}
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              {/* Preview */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-3)', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)' }}>
                <div style={{
                  width: 48, height: 48, borderRadius: 'var(--radius-md)',
                  background: `${form.color}22`,
                  border: `2px solid ${form.color}55`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24,
                }}>
                  {form.icon}
                </div>
                <p style={{ fontWeight: 600 }}>{form.name || 'Nome da categoria'}</p>
              </div>

              <div className="input-group">
                <label htmlFor="cat-name" className="input-label">Nome *</label>
                <input
                  id="cat-name"
                  type="text"
                  className="input"
                  placeholder="Ex: Importação"
                  value={form.name}
                  onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                />
              </div>

              {/* Color picker */}
              <div className="input-group">
                <label className="input-label">Cor</label>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--space-2)' }}>
                  {PRESET_COLORS.map(color => (
                    <button
                      key={color}
                      onClick={() => setForm(f => ({ ...f, color }))}
                      style={{
                        width: 32, height: 32, borderRadius: '50%',
                        background: color,
                        border: form.color === color ? '3px solid white' : '3px solid transparent',
                        outline: form.color === color ? `2px solid ${color}` : 'none',
                        cursor: 'pointer',
                        transition: 'transform 0.15s',
                        transform: form.color === color ? 'scale(1.15)' : 'scale(1)',
                      }}
                      aria-label={`Cor ${color}`}
                      aria-pressed={form.color === color}
                    />
                  ))}
                </div>
              </div>

              {/* Icon picker */}
              <div className="input-group">
                <label className="input-label">Ícone</label>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--space-2)' }}>
                  {PRESET_ICONS.map(icon => (
                    <button
                      key={icon}
                      onClick={() => setForm(f => ({ ...f, icon }))}
                      style={{
                        width: 40, height: 40, borderRadius: 'var(--radius-md)',
                        background: form.icon === icon ? `${form.color}33` : 'var(--surface-2)',
                        border: form.icon === icon ? `2px solid ${form.color}` : '2px solid transparent',
                        fontSize: 20, cursor: 'pointer',
                        transition: 'background 0.15s, border 0.15s',
                      }}
                      aria-label={`Ícone ${icon}`}
                      aria-pressed={form.icon === icon}
                    >
                      {icon}
                    </button>
                  ))}
                </div>
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-save-category"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleSave}
                  disabled={saving}
                >
                  {saving ? 'Salvando...' : editing ? 'Salvar' : 'Criar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete confirmation */}
      {deleteTarget && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setDeleteTarget(null)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-cat-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-4)' }}>
              <div style={{ width: 48, height: 48, borderRadius: 'var(--radius-full)', background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <AlertCircle size={24} color="var(--urgent)" />
              </div>
              <div>
                <h2 id="delete-cat-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>Excluir categoria?</h2>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>{deleteTarget.name}</p>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setDeleteTarget(null)}>
                Cancelar
              </button>
              <button
                id="btn-confirm-delete-cat"
                className="btn btn-danger"
                style={{ flex: 1 }}
                onClick={() => deleteMutation.mutate(deleteTarget.id)}
                disabled={deleteMutation.isPending}
              >
                {deleteMutation.isPending ? 'Excluindo...' : 'Excluir'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}
