import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  RefreshCcw, Plus, Pencil, Trash2, ArrowLeft, AlertCircle,
  Pause, Play, Calendar, DollarSign,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { Recurrence } from '../types/database';
import { formatCurrency, formatDateShort } from '../lib/utils';

const FREQ_LABELS: Record<string, string> = {
  weekly: 'Semanal',
  monthly: 'Mensal',
  yearly: 'Anual',
};

function useRecurrences(orgId: string | undefined) {
  return useQuery({
    queryKey: ['recurrences', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data, error } = await supabase
        .from('recurrences')
        .select('*')
        .eq('org_id', orgId)
        .order('next_due');
      if (error) throw error;
      return (data ?? []) as Recurrence[];
    },
    enabled: !!orgId,
  });
}

interface RecurrenceFormData {
  description: string;
  amount: string;
  frequency: 'weekly' | 'monthly' | 'yearly';
  day_of_month: string;
  next_due: string;
}

const emptyForm: RecurrenceFormData = {
  description: '',
  amount: '',
  frequency: 'monthly',
  day_of_month: '',
  next_due: new Date().toISOString().split('T')[0],
};

export default function RecurrencesPage() {
  const { currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Recurrence | null>(null);
  const [form, setForm] = useState<RecurrenceFormData>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Recurrence | null>(null);

  const { data: recurrences = [], isLoading } = useRecurrences(currentOrg?.org_id);

  const active = recurrences.filter(r => r.active);
  const paused = recurrences.filter(r => !r.active);

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setShowModal(true);
  }

  function openEdit(r: Recurrence) {
    setEditing(r);
    setForm({
      description: r.description ?? '',
      amount: r.amount != null ? String(r.amount) : '',
      frequency: r.frequency,
      day_of_month: r.day_of_month != null ? String(r.day_of_month) : '',
      next_due: r.next_due,
    });
    setShowModal(true);
  }

  async function handleSave() {
    if (!currentOrg || !form.description.trim()) {
      toast('Informe a descrição.', 'error');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        description: form.description.trim(),
        amount: form.amount ? parseFloat(form.amount.replace(',', '.')) : null,
        frequency: form.frequency,
        day_of_month: form.day_of_month ? parseInt(form.day_of_month) : null,
        next_due: form.next_due,
      };

      if (editing) {
        const { error } = await supabase.from('recurrences').update(payload).eq('id', editing.id);
        if (error) throw error;
        toast('Recorrência atualizada!', 'success');
      } else {
        const { error } = await supabase.from('recurrences').insert({ ...payload, org_id: currentOrg.org_id, active: true });
        if (error) throw error;
        toast('Recorrência criada!', 'success');
      }
      queryClient.invalidateQueries({ queryKey: ['recurrences'] });
      setShowModal(false);
    } catch {
      toast('Erro ao salvar recorrência.', 'error');
    } finally {
      setSaving(false);
    }
  }

  const toggleActiveMutation = useMutation({
    mutationFn: async ({ id, active }: { id: string; active: boolean }) => {
      const { error } = await supabase.from('recurrences').update({ active }).eq('id', id);
      if (error) throw error;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['recurrences'] });
      toast(variables.active ? 'Recorrência reativada.' : 'Recorrência pausada.', 'success');
    },
    onError: () => toast('Erro ao atualizar status.', 'error'),
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from('recurrences').delete().eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['recurrences'] });
      toast('Recorrência excluída.', 'success');
      setDeleteTarget(null);
    },
    onError: () => toast('Erro ao excluir recorrência.', 'error'),
  });

  function RecurrenceItem({ rec }: { rec: Recurrence }) {
    return (
      <div className="card" style={{ padding: 'var(--space-4)', display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
        <div style={{
          width: 44, height: 44, borderRadius: 'var(--radius-md)',
          background: rec.active ? 'var(--brand-dim)' : 'var(--surface-2)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
        }}>
          <RefreshCcw size={20} color={rec.active ? 'var(--brand)' : 'var(--text-muted)'} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', marginBottom: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {rec.description ?? 'Sem descrição'}
          </p>
          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', flexWrap: 'wrap' }}>
            <span className="chip chip-neutral" style={{ fontSize: 10 }}>
              {FREQ_LABELS[rec.frequency]}
            </span>
            {rec.amount != null && (
              <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <DollarSign size={11} /> {formatCurrency(rec.amount)}
              </span>
            )}
            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: 4 }}>
              <Calendar size={11} /> {formatDateShort(rec.next_due)}
            </span>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 'var(--space-1)', flexShrink: 0 }}>
          <button
            className="btn-ghost btn-icon btn-sm"
            onClick={() => toggleActiveMutation.mutate({ id: rec.id, active: !rec.active })}
            aria-label={rec.active ? 'Pausar recorrência' : 'Reativar recorrência'}
          >
            {rec.active ? <Pause size={16} /> : <Play size={16} />}
          </button>
          <button className="btn-ghost btn-icon btn-sm" onClick={() => openEdit(rec)} aria-label="Editar recorrência">
            <Pencil size={16} />
          </button>
          <button
            className="btn-ghost btn-icon btn-sm"
            onClick={() => setDeleteTarget(rec)}
            aria-label="Excluir recorrência"
            style={{ color: 'var(--urgent)' }}
          >
            <Trash2 size={16} />
          </button>
        </div>
      </div>
    );
  }

  return (
    <main className="page" id="page-recurrences">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Recorrências</h1>
          <button className="btn btn-primary" onClick={openCreate} id="btn-new-recurrence" aria-label="Nova recorrência">
            <Plus size={18} strokeWidth={2.5} />
            <span className="desktop-only">Nova</span>
          </button>
        </div>
      </header>

      <div className="page-content container">
        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(3)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 80, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : recurrences.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <RefreshCcw size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>Sem recorrências</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              Cadastre contas fixas (aluguel, internet, etc.) e o Cronos cria os boletos automaticamente.
            </p>
            <button className="btn btn-primary" onClick={openCreate}>
              <Plus size={16} /> Criar recorrência
            </button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-5)' }}>
            {active.length > 0 && (
              <div>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-2)' }}>
                  Ativas ({active.length})
                </p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
                  {active.map(r => <RecurrenceItem key={r.id} rec={r} />)}
                </div>
              </div>
            )}
            {paused.length > 0 && (
              <div>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-2)' }}>
                  Pausadas ({paused.length})
                </p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', opacity: 0.7 }}>
                  {paused.map(r => <RecurrenceItem key={r.id} rec={r} />)}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Create/Edit Modal */}
      {showModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="rec-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="rec-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              {editing ? 'Editar recorrência' : 'Nova recorrência'}
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div className="input-group">
                <label htmlFor="rec-desc" className="input-label">Descrição *</label>
                <input
                  id="rec-desc"
                  type="text"
                  className="input"
                  placeholder="Ex: Aluguel do espaço"
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                />
              </div>

              <div className="input-group">
                <label htmlFor="rec-amount" className="input-label">Valor aproximado (R$)</label>
                <input
                  id="rec-amount"
                  type="number"
                  step="0.01"
                  className="input amount"
                  placeholder="0,00 (opcional)"
                  value={form.amount}
                  onChange={e => setForm(f => ({ ...f, amount: e.target.value }))}
                />
              </div>

              <div className="input-group">
                <label htmlFor="rec-frequency" className="input-label">Frequência *</label>
                <select
                  id="rec-frequency"
                  className="input"
                  value={form.frequency}
                  onChange={e => setForm(f => ({ ...f, frequency: e.target.value as RecurrenceFormData['frequency'] }))}
                >
                  <option value="weekly">Semanal</option>
                  <option value="monthly">Mensal</option>
                  <option value="yearly">Anual</option>
                </select>
              </div>

              {form.frequency === 'monthly' && (
                <div className="input-group">
                  <label htmlFor="rec-day" className="input-label">Dia do mês (1–31)</label>
                  <input
                    id="rec-day"
                    type="number"
                    min="1"
                    max="31"
                    className="input"
                    placeholder="Ex: 10"
                    value={form.day_of_month}
                    onChange={e => setForm(f => ({ ...f, day_of_month: e.target.value }))}
                  />
                </div>
              )}

              <div className="input-group">
                <label htmlFor="rec-next" className="input-label">Próximo vencimento *</label>
                <input
                  id="rec-next"
                  type="date"
                  className="input"
                  value={form.next_due}
                  onChange={e => setForm(f => ({ ...f, next_due: e.target.value }))}
                />
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-save-recurrence"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleSave}
                  disabled={saving}
                >
                  {saving ? 'Salvando...' : editing ? 'Salvar' : 'Criar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete confirmation */}
      {deleteTarget && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setDeleteTarget(null)}
          role="dialog"
          aria-modal="true"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-4)' }}>
              <div style={{ width: 48, height: 48, borderRadius: 'var(--radius-full)', background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <AlertCircle size={24} color="var(--urgent)" />
              </div>
              <div>
                <h2 style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>Excluir recorrência?</h2>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>{deleteTarget.description}</p>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setDeleteTarget(null)}>Cancelar</button>
              <button
                id="btn-confirm-delete-rec"
                className="btn btn-danger"
                style={{ flex: 1 }}
                onClick={() => deleteMutation.mutate(deleteTarget.id)}
                disabled={deleteMutation.isPending}
              >
                {deleteMutation.isPending ? 'Excluindo...' : 'Excluir'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}
