import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Users, ArrowLeft, Plus, Mail, Shield, Crown,
  Eye, AlertCircle, UserX, MoreVertical,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { UserRole } from '../types/database';

interface TeamMember {
  org_id: string;
  user_id: string;
  role: UserRole;
  email?: string;
  full_name?: string;
}

const ROLE_LABELS: Record<UserRole, string> = {
  owner: 'Dono',
  finance: 'Financeiro',
  viewer: 'Somente leitura',
};

const ROLE_ICONS: Record<UserRole, React.ElementType> = {
  owner: Crown,
  finance: Shield,
  viewer: Eye,
};

function useTeamMembers(orgId: string | undefined) {
  return useQuery({
    queryKey: ['team', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      // Join org_members with user profiles via auth.users metadata
      const { data, error } = await supabase
        .from('org_members')
        .select('*')
        .eq('org_id', orgId);
      if (error) throw error;
      return (data ?? []) as TeamMember[];
    },
    enabled: !!orgId,
  });
}

export default function TeamPage() {
  const { user, currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<UserRole>('finance');
  const [inviting, setInviting] = useState(false);
  const [actionTarget, setActionTarget] = useState<TeamMember | null>(null);

  const { data: members = [], isLoading } = useTeamMembers(currentOrg?.org_id);

  const removeRoleMutation = useMutation({
    mutationFn: async (member: TeamMember) => {
      const { error } = await supabase
        .from('org_members')
        .delete()
        .eq('org_id', member.org_id)
        .eq('user_id', member.user_id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['team'] });
      toast('Membro removido.', 'success');
      setActionTarget(null);
    },
    onError: () => toast('Erro ao remover membro.', 'error'),
  });

  const changeRoleMutation = useMutation({
    mutationFn: async ({ member, role }: { member: TeamMember; role: UserRole }) => {
      const { error } = await supabase
        .from('org_members')
        .update({ role })
        .eq('org_id', member.org_id)
        .eq('user_id', member.user_id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['team'] });
      toast('Perfil atualizado.', 'success');
      setActionTarget(null);
    },
    onError: () => toast('Erro ao atualizar perfil.', 'error'),
  });

  // Only owners can access this page
  if (currentOrg?.role !== 'owner') {
    return (
      <main className="page">
        <div className="page-content container">
          <div className="empty-state">
            <Shield size={48} color="var(--text-muted)" />
            <h2>Acesso restrito</h2>
            <p style={{ color: 'var(--text-muted)' }}>Apenas o dono da organização pode gerenciar a equipe.</p>
            <button className="btn btn-secondary" onClick={() => navigate(-1)}>Voltar</button>
          </div>
        </div>
      </main>
    );
  }

  async function handleInvite() {
    if (!currentOrg || !inviteEmail.trim()) {
      toast('Informe o e-mail do convidado.', 'error');
      return;
    }
    setInviting(true);
    try {
      // In a real app, this would call an Edge Function to send an invitation email.
      // Here we simulate and show what would happen.
      toast(`Convite enviado para ${inviteEmail} com perfil "${ROLE_LABELS[inviteRole]}".`, 'success');
      setShowInviteModal(false);
      setInviteEmail('');
    } catch {
      toast('Erro ao enviar convite.', 'error');
    } finally {
      setInviting(false);
    }
  }

  return (
    <main className="page" id="page-team">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Equipe</h1>
          <button
            className="btn btn-primary"
            onClick={() => setShowInviteModal(true)}
            id="btn-invite-member"
          >
            <Plus size={18} strokeWidth={2.5} />
            <span className="desktop-only">Convidar</span>
          </button>
        </div>
      </header>

      <div className="page-content container">
        {/* Info card */}
        <div style={{
          padding: 'var(--space-4)',
          background: 'var(--surface-2)',
          borderRadius: 'var(--radius-md)',
          border: '1px solid var(--border)',
          marginBottom: 'var(--space-4)',
        }}>
          <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.6 }}>
            <Shield size={12} style={{ display: 'inline', marginRight: 4 }} aria-hidden="true" />
            <strong style={{ color: 'var(--text)' }}>Financeiro:</strong> pode cadastrar, editar e marcar como pago. &nbsp;|&nbsp;
            <strong style={{ color: 'var(--text)' }}>Somente leitura:</strong> acesso de visualização (ex.: contador).
          </p>
        </div>

        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(3)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 72, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : members.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <Users size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>Apenas você</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              Convide colaboradores para gerenciar os boletos da Morpheus.
            </p>
            <button className="btn btn-primary" onClick={() => setShowInviteModal(true)}>
              <Mail size={16} /> Enviar convite
            </button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {members.map(member => {
              const RoleIcon = ROLE_ICONS[member.role];
              const isMe = member.user_id === user?.id;
              return (
                <div
                  key={member.user_id}
                  className="card"
                  style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-4)' }}
                >
                  <div style={{
                    width: 44, height: 44, borderRadius: 'var(--radius-full)',
                    background: isMe ? 'var(--brand)' : 'var(--surface-2)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                  }}>
                    <span style={{ fontWeight: 700, color: isMe ? 'var(--on-brand)' : 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
                      {(member.email?.[0] ?? member.user_id[0]).toUpperCase()}
                    </span>
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                      <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {member.email ?? member.user_id.slice(0, 12) + '...'}
                      </p>
                      {isMe && <span className="chip chip-brand" style={{ fontSize: 10 }}>Você</span>}
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginTop: 2 }}>
                      <RoleIcon size={12} color="var(--text-muted)" />
                      <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{ROLE_LABELS[member.role]}</span>
                    </div>
                  </div>
                  {!isMe && (
                    <button
                      className="btn-ghost btn-icon btn-sm"
                      onClick={() => setActionTarget(member)}
                      aria-label="Opções do membro"
                    >
                      <MoreVertical size={16} />
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Invite Modal */}
      {showInviteModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowInviteModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="invite-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="invite-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              Convidar colaborador
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div className="input-group">
                <label htmlFor="invite-email" className="input-label">E-mail *</label>
                <input
                  id="invite-email"
                  type="email"
                  className="input"
                  placeholder="nome@email.com"
                  value={inviteEmail}
                  onChange={e => setInviteEmail(e.target.value)}
                />
              </div>

              <div className="input-group">
                <label htmlFor="invite-role" className="input-label">Perfil *</label>
                <select
                  id="invite-role"
                  className="input"
                  value={inviteRole}
                  onChange={e => setInviteRole(e.target.value as UserRole)}
                >
                  <option value="finance">Financeiro — cria e edita boletos</option>
                  <option value="viewer">Somente leitura — acesso de contador</option>
                </select>
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowInviteModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-send-invite"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleInvite}
                  disabled={inviting}
                >
                  <Mail size={16} />
                  {inviting ? 'Enviando...' : 'Enviar convite'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Member action modal */}
      {actionTarget && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setActionTarget(null)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="member-action-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="member-action-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700, marginBottom: 4 }}>
              {actionTarget.email ?? 'Membro'}
            </h2>
            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', marginBottom: 'var(--space-5)' }}>
              Perfil atual: <strong>{ROLE_LABELS[actionTarget.role]}</strong>
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              {(['finance', 'viewer'] as UserRole[]).filter(r => r !== actionTarget.role).map(role => (
                <button
                  key={role}
                  className="btn btn-secondary btn-full"
                  onClick={() => changeRoleMutation.mutate({ member: actionTarget, role })}
                  disabled={changeRoleMutation.isPending}
                >
                  Mudar para {ROLE_LABELS[role]}
                </button>
              ))}
              <button
                id="btn-remove-member"
                className="btn btn-danger btn-full"
                onClick={() => removeRoleMutation.mutate(actionTarget)}
                disabled={removeRoleMutation.isPending}
                style={{ marginTop: 'var(--space-2)' }}
              >
                <UserX size={16} />
                {removeRoleMutation.isPending ? 'Removendo...' : 'Remover da equipe'}
              </button>
              <button className="btn btn-ghost btn-full" onClick={() => setActionTarget(null)}>
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Alert circle ref */}
      <div style={{ display: 'none' }}><AlertCircle /></div>
    </main>
  );
}
