import { differenceInCalendarDays, format, isToday, isTomorrow, isYesterday, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import type { BillUrgency, BillView } from '../types/database';

// ── Currency formatting ─────────────────────────────────────
export function formatCurrency(value: number): string {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
}

export function formatCurrencyCompact(value: number): string {
  if (value >= 1_000_000) {
    return `R$ ${(value / 1_000_000).toFixed(1)}M`;
  }
  if (value >= 1_000) {
    return `R$ ${(value / 1_000).toFixed(1)}k`;
  }
  return formatCurrency(value);
}

// ── Date formatting ─────────────────────────────────────────
export function formatDate(dateStr: string): string {
  const date = parseISO(dateStr);
  if (isToday(date)) return 'Hoje';
  if (isTomorrow(date)) return 'Amanhã';
  if (isYesterday(date)) return 'Ontem';
  return format(date, "d 'de' MMM", { locale: ptBR });
}

export function formatDateFull(dateStr: string): string {
  return format(parseISO(dateStr), "d 'de' MMMM 'de' yyyy", { locale: ptBR });
}

export function formatDateShort(dateStr: string): string {
  return format(parseISO(dateStr), 'dd/MM/yyyy');
}

export function daysToDate(dateStr: string): number {
  return differenceInCalendarDays(parseISO(dateStr), new Date());
}

// ── Urgency calculation ─────────────────────────────────────
export function getUrgency(dueDate: string, status: string): BillUrgency {
  if (status === 'paid' || status === 'canceled') return 'paid';
  const days = daysToDate(dueDate);
  if (days <= 0) return 'urgent';
  if (days <= 7) return 'soon';
  return 'ok';
}

