// ── Due date label ─────────────────────────────────────────
export function getDueDateLabel(dueDate: string, status: string): string {
  if (status === 'paid') return 'Pago';
  if (status === 'canceled') return 'Cancelado';
  const days = daysToDate(dueDate);
  if (days < 0) return `Atrasado há ${Math.abs(days)} dia${Math.abs(days) > 1 ? 's' : ''}`;
  if (days === 0) return 'Vence hoje';
  if (days === 1) return 'Vence amanhã';
  return `Vence em ${days} dias`;
}

// ── Barcode validation ──────────────────────────────────────
export function validateBarcodeLine(line: string): boolean {
  const digits = line.replace(/\D/g, '');
  return digits.length === 47 || digits.length === 48;
}

export function parseBarcodeDate(factorStr: string): Date | null {
  const factor = parseInt(factorStr, 10);
  if (!factor || factor === 0) return null;

  // Fator de vencimento: dias desde 07/10/1997
  // Reinicia em 1000 a partir de 22/02/2025 (depois de atingir 9999)
  const base = new Date('1997-10-07');
  const RESTART_FACTOR = 1000;
  const RESTART_DATE = new Date('2025-02-22');

  let days = factor;
  if (factor < RESTART_FACTOR) {
    // Factor wrapped around — add offset from restart date
    const daysFromBase = differenceInCalendarDays(RESTART_DATE, base);
    days = daysFromBase + (factor - RESTART_FACTOR + 9000);
  }

  const result = new Date(base);
  result.setDate(result.getDate() + days);
  return result;
}

export function formatBarcodeDisplay(line: string): string {
  const d = line.replace(/\D/g, '');
  if (d.length === 47) {
    // Boleto bancário: AAAAA.BBBBB CCCCC.DDDDDD EEEEE.FFFFFF G HHHHHHHHHHHHHHHHH
    return `${d.slice(0,5)}.${d.slice(5,10)} ${d.slice(10,15)}.${d.slice(15,21)} ${d.slice(21,26)}.${d.slice(26,32)} ${d.slice(32,33)} ${d.slice(33)}`;
  }
  if (d.length === 48) {
    return `${d.slice(0, 11)}-${d.slice(11, 12)} ${d.slice(12, 23)}-${d.slice(23, 24)} ${d.slice(24, 35)}-${d.slice(35, 36)} ${d.slice(36, 47)}-${d.slice(47, 48)}`;
  }
  return line;
}

export interface ExtractedBoletoInfo {
  barcodeLine: string;
  formattedLine: string;
  amount: number | null;
  dueDate: string | null;
  bankName?: string;
}

export function extractBoletoData(rawLine: string): ExtractedBoletoInfo | null {
  const digits = rawLine.replace(/\D/g, '');
  if (digits.length !== 47 && digits.length !== 48) return null;

  if (digits.length === 47) {
    const factorStr = digits.slice(33, 37);
    const valueStr = digits.slice(37, 47);
    const parsedDate = parseBarcodeDate(factorStr);
    const dueDate = parsedDate ? format(parsedDate, 'yyyy-MM-dd') : null;
    const centavos = parseInt(valueStr, 10);
    const amount = isNaN(centavos) || centavos === 0 ? null : centavos / 100;

    const bankCode = digits.slice(0, 3);
    const banks: Record<string, string> = {
      '001': 'Banco do Brasil',
      '033': 'Santander',
      '104': 'Caixa Econômica Federal',
      '237': 'Bradesco',
      '341': 'Itaú Unibanco',
      '748': 'Sicredi',
      '756': 'Sicoob',
      '260': 'Nubank',
      '077': 'Banco Inter',
    };
    const bankName = banks[bankCode] || `Banco ${bankCode}`;

    return {
      barcodeLine: digits,
      formattedLine: formatBarcodeDisplay(digits),
      amount,
      dueDate,
      bankName,
    };
  }

  return {
    barcodeLine: digits,
    formattedLine: formatBarcodeDisplay(digits),
    amount: null,
    dueDate: null,
    bankName: 'Concessionária / Tributo',
  };
}

// ── Group bills by due date ─────────────────────────────────
export interface BillGroup {
  label: string;
  date: string;
  bills: BillView[];
}

export function groupBillsByDate(bills: BillView[]): BillGroup[] {
  const map = new Map<string, BillView[]>();
  for (const bill of bills) {
    const key = bill.due_date;
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(bill);
  }
  return Array.from(map.entries()).map(([date, bills]) => ({
    label: formatDate(date),
    date,
    bills,
  }));
}

// ── Interest paid ────────────────────────────────────────────
export function calcInterestPaid(amount: number, paidAmount: number | null): number {
  if (!paidAmount || paidAmount <= amount) return 0;
  return paidAmount - amount;
}

// ── Detect platform ──────────────────────────────────────────
export function getPlatform(): 'ios' | 'android' | 'web' {
  const ua = navigator.userAgent;
  if (/iPad|iPhone|iPod/.test(ua)) return 'ios';
  if (/Android/.test(ua)) return 'android';
  return 'web';
}

export function isStandalone(): boolean {
  if (typeof window === 'undefined') return false;
  return (
    window.matchMedia('(display-mode: standalone)').matches ||
    window.matchMedia('(display-mode: fullscreen)').matches ||
    window.matchMedia('(display-mode: minimal-ui)').matches ||
    (window.navigator as any).standalone === true ||
    document.referrer.includes('android-app://')
  );
}
