import { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import {
  Building2, Tag, Truck, RefreshCcw,
  Bell, Users, Settings, LogOut, ChevronRight,
  FileBarChart2, Smartphone,
} from 'lucide-react';
import { PwaInstallBanner } from '../components/PwaInstallBanner';
import { getInstallPrompt } from '../lib/pwa';

interface MenuItem {
  id: string;
  icon: React.ElementType;
  label: string;
  description?: string;
  route?: string;
  action?: () => void;
  role?: 'owner' | 'finance';
  danger?: boolean;
}

export default function MorePage() {
  const { user, currentOrg, signOut } = useAuth();
  const navigate = useNavigate();
  const [showPwaModal, setShowPwaModal] = useState(false);

  const menuItems: MenuItem[] = [
    { id: 'suppliers', icon: Truck, label: 'Fornecedores', route: '/fornecedores' },
    { id: 'categories', icon: Tag, label: 'Categorias', route: '/categorias' },
    { id: 'recurrences', icon: RefreshCcw, label: 'Recorrências', route: '/recorrencias' },
    { id: 'reports', icon: FileBarChart2, label: 'Relatórios', route: '/relatorios' },
    { id: 'notifications', icon: Bell, label: 'Notificações', route: '/notificacoes' },
    {
      id: 'install_pwa',
      icon: Smartphone,
      label: 'Instalar no celular (PWA)',
      description: 'Atalhos e notificações push na tela inicial',
      action: async () => {
        const prompt = getInstallPrompt();
        if (prompt) {
          try {
            await prompt.prompt();
            const choice = await prompt.userChoice;
            if (choice?.outcome !== 'accepted') {
              setShowPwaModal(true);
            }
          } catch {
            setShowPwaModal(true);
          }
        } else {
          setShowPwaModal(true);
        }
      },
    },
    { id: 'team', icon: Users, label: 'Equipe', description: 'Convidar e gerenciar membros', route: '/equipe', role: 'owner' },
    { id: 'settings', icon: Settings, label: 'Configurações', route: '/configuracoes' },
    {
      id: 'logout', icon: LogOut, label: 'Sair', danger: true,
      action: async () => {
        await signOut();
        navigate('/login');
      },
    },
  ];

  const firstName = user?.user_metadata?.full_name?.split(' ')[0] ?? user?.email?.split('@')[0] ?? 'Usuário';

  return (
    <main className="page" id="page-more">
      <header className="page-header">
        <div className="container">
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700 }}>Mais</h1>
        </div>
      </header>

      <div className="page-content container">
        {/* User profile card */}
        <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-4)' }}>
          <div style={{
            width: 52, height: 52, borderRadius: 'var(--radius-full)',
            background: 'var(--brand)', display: 'flex',
            alignItems: 'center', justifyContent: 'center',
            flexShrink: 0,
          }}>
            <span style={{ fontFamily: 'Montserrat', fontSize: 'var(--text-lg)', fontWeight: 900, color: 'var(--on-brand)' }}>
              {firstName.charAt(0).toUpperCase()}
            </span>
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <p style={{ fontWeight: 700, fontSize: 'var(--text-base)' }}>{firstName}</p>
            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {user?.email}
            </p>
            {currentOrg && (
              <span className="chip chip-brand" style={{ marginTop: 'var(--space-1)' }}>
                {currentOrg.role === 'owner' ? 'Dono' : currentOrg.role === 'finance' ? 'Financeiro' : 'Somente leitura'}
              </span>
            )}
          </div>
        </div>

        {/* Org info */}
        {currentOrg && (
          <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <Building2 size={20} color="var(--text-muted)" aria-hidden="true" />
            <div>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Organização</p>
              <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>{currentOrg.organization.name}</p>
            </div>
          </div>
        )}

        {/* Menu items */}
        <nav aria-label="Menu de navegação">
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {menuItems
              .filter(item => !item.role || item.role === currentOrg?.role)
              .map(item => {
                const Icon = item.icon;
                return (
                  <button
                    key={item.id}
                    id={`menu-${item.id}`}
                    className="card card-hover"
                    style={{
                      display: 'flex', alignItems: 'center', gap: 'var(--space-3)',
                      cursor: 'pointer', border: '1px solid var(--border)', textAlign: 'left',
                      background: 'var(--surface)', color: 'var(--text)',
                      width: '100%',
                    }}
                    onClick={() => item.action ? item.action() : item.route && navigate(item.route)}
                    aria-label={item.label}
                  >
                    <div style={{
                      width: 40, height: 40, borderRadius: 'var(--radius-md)',
                      background: item.danger ? 'var(--urgent-bg)' : 'var(--surface-2)',
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      flexShrink: 0,
                    }}>
                      <Icon size={18} color={item.danger ? 'var(--urgent)' : 'var(--text-muted)'} aria-hidden="true" />
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', color: item.danger ? 'var(--urgent)' : 'var(--text)' }}>
                        {item.label}
                      </p>
                      {item.description && (
                        <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{item.description}</p>
                      )}
                    </div>
                    <ChevronRight size={16} color="var(--text-subtle)" aria-hidden="true" />
                  </button>
                );
              })}
          </div>
        </nav>

        <p style={{ textAlign: 'center', fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', paddingTop: 'var(--space-4)' }}>
          Cronos v1.0 · Morpheus Relojoaria
        </p>

        {showPwaModal && (
          <div
            style={{
              position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)',
              backdropFilter: 'blur(8px)', zIndex: 100,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              padding: 16,
            }}
            onClick={() => setShowPwaModal(false)}
          >
            <div
              style={{ maxWidth: 440, width: '100%' }}
              onClick={e => e.stopPropagation()}
            >
              <PwaInstallBanner forceOpen={true} onClose={() => setShowPwaModal(false)} />
            </div>
          </div>
        )}
      </div>
    </main>
  );
}
