import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Sparkles, Send, Bot, User as UserIcon, Plus, ArrowRight } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { formatCurrency, formatDate, daysToDate, calcInterestPaid } from '../lib/utils';
import { useQuery } from '@tanstack/react-query';
import type { BillView, Supplier } from '../types/database';

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  createdAt: string;
  action?: {
    label: string;
    route: string;
  };
  metrics?: {
    total?: number;
    count?: number;
    highlight?: string;
  };
}

// Answer engine with real database values
function generateAnswer(
  query: string,
  bills: BillView[],
  suppliers: Supplier[]
): {
  content: string;
  action?: { label: string; route: string };
  metrics?: { total?: number; count?: number; highlight?: string };
} {
  const q = query.toLowerCase().trim();

  // 1. Atrasados
  if (q.includes('atrasad') || q.includes('vencid')) {
    const overdue = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) < 0);
    const total = overdue.reduce((sum, b) => sum + Number(b.amount), 0);

    if (overdue.length === 0) {
      return {
        content: 'Excelente notícia! Não há nenhum boleto atrasado na sua empresa no momento. Tudo está em dia.',
        action: { label: 'Ver todos os boletos', route: '/boletos' },
      };
    }

    const listSample = overdue
      .slice(0, 3)
      .map(b => `• ${b.beneficiary_name || 'Boleto'}: ${formatCurrency(b.amount)} (venceu ${formatDate(b.due_date)})`)
      .join('\n');

    return {
      content: `Você tem ${overdue.length} boleto${overdue.length > 1 ? 's' : ''} atrasado${overdue.length > 1 ? 's' : ''}, somando ${formatCurrency(total)}.\n\n${listSample}${overdue.length > 3 ? `\n... e mais ${overdue.length - 3} conta(s).` : ''}`,
      action: { label: 'Visualizar boletos atrasados', route: '/boletos' },
      metrics: { total, count: overdue.length, highlight: 'Atenção imediata' },
    };
  }

  // 2. Semana
  if (q.includes('semana')) {
    const thisWeek = bills.filter(b => {
      if (b.status !== 'pending') return false;
      const days = daysToDate(b.due_date);
      return days >= 0 && days <= 7;
    });
    const total = thisWeek.reduce((sum, b) => sum + Number(b.amount), 0);

    if (thisWeek.length === 0) {
      return {
        content: 'Você não tem nenhum boleto agendado para vencer nos próximos 7 dias. Seu fluxo de caixa está tranquilo!',
        action: { label: 'Ver contas do mês', route: '/boletos' },
      };
    }

    const listSample = thisWeek
      .slice(0, 4)
      .map(b => `• ${b.beneficiary_name || 'Boleto'}: ${formatCurrency(b.amount)} (${formatDate(b.due_date)})`)
      .join('\n');

    return {
      content: `Para os próximos 7 dias, você tem ${thisWeek.length} boleto${thisWeek.length > 1 ? 's' : ''} a pagar, totalizando ${formatCurrency(total)}:\n\n${listSample}`,
      action: { label: 'Ver boletos da semana', route: '/boletos' },
      metrics: { total, count: thisWeek.length, highlight: 'Próximos 7 dias' },
    };
  }

  // 3. Hoje ou amanhã
  if (q.includes('hoje')) {
    const todayBills = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) === 0);
    const total = todayBills.reduce((sum, b) => sum + Number(b.amount), 0);

    if (todayBills.length === 0) {
      return {
        content: 'Nenhum boleto vence hoje! Nada pendente para quitação imediata nas próximas horas.',
      };
    }

    const listSample = todayBills
      .map(b => `• ${b.beneficiary_name || 'Boleto'}: ${formatCurrency(b.amount)}`)
      .join('\n');

    return {
      content: `Hoje você precisa pagar ${todayBills.length} boleto${todayBills.length > 1 ? 's' : ''}, somando ${formatCurrency(total)}:\n\n${listSample}`,
      action: { label: 'Abrir boletos de hoje', route: '/boletos' },
      metrics: { total, count: todayBills.length, highlight: 'Vence hoje' },
    };
  }

  if (q.includes('amanhã') || q.includes('amanha')) {
    const tomorrowBills = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) === 1);
    const total = tomorrowBills.reduce((sum, b) => sum + Number(b.amount), 0);

    if (tomorrowBills.length === 0) {
      return {
        content: 'Não há boletos com vencimento marcado para amanhã.',
      };
    }

    return {
      content: `Amanhã vence${tomorrowBills.length > 1 ? 'm' : ''} ${tomorrowBills.length} boleto${tomorrowBills.length > 1 ? 's' : ''}, no valor total de ${formatCurrency(total)}.`,
      action: { label: 'Ver lista de boletos', route: '/boletos' },
      metrics: { total, count: tomorrowBills.length },
    };
  }

  // 4. Juros
  if (q.includes('juros') || q.includes('multa')) {
    const paidBills = bills.filter(b => b.status === 'paid');
    const totalInterest = paidBills.reduce((acc, b) => acc + calcInterestPaid(Number(b.amount), b.paid_amount), 0);

    if (totalInterest === 0) {
      return {
        content: 'Parabéns! Nenhum centavo de juros ou multa foi pago em boletos este ano. Sua pontualidade está gerando economia máxima!',
        action: { label: 'Ver relatórios financeiros', route: '/relatorios' },
      };
    }

    return {
      content: `No acumulado, a empresa pagou um total de ${formatCurrency(totalInterest)} em juros e multas por atraso. Pagar no vencimento garante economia direta.`,
      action: { label: 'Consultar relatório detalhado', route: '/relatorios' },
      metrics: { total: totalInterest, highlight: 'Juros acumulados' },
    };
  }

  // 5. Mês atual
  if (q.includes('mês') || q.includes('mes')) {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthBills = bills.filter(b => {
      const d = new Date(b.due_date + 'T00:00:00');
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const pending = monthBills.filter(b => b.status === 'pending');
    const paid = monthBills.filter(b => b.status === 'paid');
    const totalPending = pending.reduce((sum, b) => sum + Number(b.amount), 0);
    const totalPaid = paid.reduce((sum, b) => sum + (b.paid_amount ?? Number(b.amount)), 0);

    return {
      content: `Visão geral deste mês:\n• Total a pagar (pendente): ${formatCurrency(totalPending)} (${pending.length} boletos)\n• Total já pago: ${formatCurrency(totalPaid)} (${paid.length} boletos)`,
      action: { label: 'Ver dashboard completo', route: '/' },
      metrics: { total: totalPending, highlight: 'A pagar no mês' },
    };
  }

  // 6. Fornecedor específico
  for (const sup of suppliers) {
    if (q.includes(sup.name.toLowerCase())) {
      const supBills = bills.filter(b => b.supplier_id === sup.id && b.status === 'pending');
      const total = supBills.reduce((sum, b) => sum + Number(b.amount), 0);

      if (supBills.length === 0) {
        return {
          content: `Você não tem contas pendentes para ${sup.name}. Todos os boletos estão quitados!`,
          action: { label: 'Ver fornecedor', route: '/fornecedores' },
        };
      }

      return {
        content: `Você deve ${formatCurrency(total)} para ${sup.name}, distribuídos em ${supBills.length} boleto(s) em aberto.`,
        action: { label: `Ver boletos de ${sup.name}`, route: '/boletos' },
        metrics: { total, count: supBills.length, highlight: sup.name },
      };
    }
  }

  // Default friendly answer
  const pendingTotal = bills.filter(b => b.status === 'pending').reduce((sum, b) => sum + Number(b.amount), 0);
  return {
    content: `Atualmente sua organização tem ${formatCurrency(pendingTotal)} em contas pendentes. Você pode me perguntar sobre boletos de hoje, da semana, boletos atrasados, juros pagos ou quanto deve a algum fornecedor (ex: Casio, Seiko).`,
    action: { label: 'Ir para Central de Pagamentos', route: '/' },
  };
}

export default function AssistantPage() {
  const { currentOrg, user } = useAuth();
  const navigate = useNavigate();
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);

  // Load all bills for the active organization to compute real financial numbers
  const { data: bills = [] } = useQuery({
    queryKey: ['bills_all', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase
        .from('bills_view')
        .select('*')
        .eq('org_id', currentOrg.org_id)
        .order('due_date', { ascending: true });
      return (data ?? []) as BillView[];
    },
    enabled: !!currentOrg?.org_id,
  });

  const { data: suppliers = [] } = useQuery({
    queryKey: ['suppliers_all', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase
        .from('suppliers')
        .select('*')
        .eq('org_id', currentOrg.org_id);
      return (data ?? []) as Supplier[];
    },
    enabled: !!currentOrg?.org_id,
  });

  // Initialize or fetch conversation
  useEffect(() => {
    if (!currentOrg || !user) return;

    async function initConversation() {
      try {
        const { data: convs } = await supabase
          .from('ai_conversations')
          .select('id, title')
          .eq('org_id', currentOrg!.org_id)
          .eq('user_id', user!.id)
          .order('updated_at', { ascending: false })
          .limit(1);

        if (convs && convs.length > 0) {
          const activeConv = convs[0];
          setConversationId(activeConv.id);

          // Fetch messages
          const { data: dbMessages } = await supabase
            .from('ai_messages')
            .select('*')
            .eq('conversation_id', activeConv.id)
            .order('created_at', { ascending: true });

          if (dbMessages && dbMessages.length > 0) {
            setMessages(
              dbMessages.map(m => ({
                id: m.id,
                role: m.role as 'user' | 'assistant',
                content: m.content,
                createdAt: m.created_at,
              }))
            );
            return;
          }
        } else {
          // Create initial conversation
          const { data: newConv } = await supabase
            .from('ai_conversations')
            .insert({
              org_id: currentOrg!.org_id,
              user_id: user!.id,
              title: 'Atendimento Financeiro',
            })
            .select()
            .single();

          if (newConv) setConversationId(newConv.id);
        }
      } catch (err) {
        console.warn('AI conversation init fallback:', err);
      }

      // Initial greeting if no messages
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `Olá! Sou o Assistente Financeiro do Cronos. Estou conectado aos boletos e despesas da ${currentOrg?.organization?.name || 'sua empresa'}. Como posso te ajudar hoje?`,
          createdAt: new Date().toISOString(),
        },
      ]);
    }

    initConversation();
  }, [currentOrg, user]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  async function handleSend(textToSend?: string) {
    const query = textToSend || input;
    if (!query.trim() || loading) return;

    setInput('');
    const now = new Date();
    const userMsgId = 'user-' + now.getTime();
    const newMsg: ChatMessage = {
      id: userMsgId,
      role: 'user',
      content: query.trim(),
      createdAt: now.toISOString(),
    };

    setMessages(prev => [...prev, newMsg]);
    setLoading(true);

    // Save user message to Supabase if conversation exists
    if (conversationId) {
      void supabase.from('ai_messages').insert({
        conversation_id: conversationId,
        role: 'user',
        content: query.trim(),
      }).then(() => {}, (err: unknown) => console.warn('Supabase message persist:', err));
    }

    // Simulate smart thinking delay
    setTimeout(async () => {
      const response = generateAnswer(query, bills, suppliers);
      const resNow = new Date();
      const assistantMsg: ChatMessage = {
        id: 'assistant-' + resNow.getTime(),
        role: 'assistant',
        content: response.content,
        createdAt: resNow.toISOString(),
        action: response.action,
        metrics: response.metrics,
      };

      setMessages(prev => [...prev, assistantMsg]);
      setLoading(false);

      if (conversationId) {
        void supabase.from('ai_messages').insert({
          conversation_id: conversationId,
          role: 'assistant',
          content: response.content,
          tokens_used: 120,
        }).then(() => {}, (err: unknown) => console.warn('Supabase message persist:', err));
      }
    }, 600);
  }

  const promptSuggestions = [
    'Quanto tenho para pagar essa semana?',
    'Quais boletos estão atrasados?',
    'O que vence hoje?',
    'Quanto paguei de juros este ano?',
    'Resumo do mês atual',
  ];

  return (
    <main className="page" id="page-assistant" style={{ display: 'flex', flexDirection: 'column', height: '100dvh', background: 'var(--bg)' }}>
      {/* Header */}
      <header className="page-header" style={{ flexShrink: 0 }}>
        <div className="container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{
              width: 36, height: 36, borderRadius: 'var(--radius-full)',
              background: 'var(--brand)', display: 'flex',
              alignItems: 'center', justifyContent: 'center',
            }}>
              <Sparkles size={20} color="var(--on-brand)" />
            </div>
            <div>
              <h1 style={{ fontSize: 'var(--text-base)', fontWeight: 700, margin: 0 }}>Assistente Cronos</h1>
              <span style={{ fontSize: 11, color: 'var(--ok)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--ok)' }} />
                Online · Base atualizada
              </span>
            </div>
          </div>

          <button
            className="btn-ghost btn-icon"
            onClick={() => {
              setMessages([
                {
                  id: 'welcome-' + Date.now(),
                  role: 'assistant',
                  content: 'Nova conversa iniciada. Em que posso te apoiar?',
                  createdAt: new Date().toISOString(),
                },
              ]);
            }}
            title="Nova consulta"
            aria-label="Nova conversa"
          >
            <Plus size={20} />
          </button>
        </div>
      </header>

      {/* Chat Messages Body */}
      <div style={{
        flex: 1,
        overflowY: 'auto',
        padding: '16px 0',
      }}>
        <div className="container" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {messages.map(msg => {
            const isUser = msg.role === 'user';
            return (
              <div
                key={msg.id}
                style={{
                  display: 'flex',
                  gap: 10,
                  flexDirection: isUser ? 'row-reverse' : 'row',
                  alignItems: 'flex-start',
                }}
              >
                {/* Avatar */}
                <div style={{
                  width: 32, height: 32, borderRadius: 'var(--radius-full)',
                  background: isUser ? 'var(--surface-2)' : 'var(--brand-dim)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  flexShrink: 0,
                }}>
                  {isUser ? (
                    <UserIcon size={16} color="var(--text-muted)" />
                  ) : (
                    <Bot size={18} color="var(--brand)" />
                  )}
                </div>

                {/* Message bubble */}
                <div style={{
                  maxWidth: '82%',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 8,
                }}>
                  <div style={{
                    padding: '12px 16px',
                    borderRadius: isUser ? '16px 4px 16px 16px' : '4px 16px 16px 16px',
                    background: isUser ? 'var(--brand)' : 'var(--surface)',
                    color: isUser ? 'var(--on-brand)' : 'var(--text)',
                    border: isUser ? 'none' : '1px solid var(--border)',
                    fontSize: 'var(--text-sm)',
                    lineHeight: 1.5,
                    whiteSpace: 'pre-line',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                  }}>
                    {msg.content}
                  </div>

                  {/* Highlight metric card */}
                  {msg.metrics?.total !== undefined && (
                    <div style={{
                      background: 'var(--surface-2)',
                      border: '1px solid var(--border)',
                      borderRadius: 'var(--radius-md)',
                      padding: '10px 14px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                    }}>
                      <div>
                        <span style={{ fontSize: 11, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                          {msg.metrics.highlight || 'Total Identificado'}
                        </span>
                        <p style={{ fontSize: 'var(--text-base)', fontWeight: 700, color: 'var(--brand)', margin: 0 }}>
                          {formatCurrency(msg.metrics.total)}
                        </p>
                      </div>
                      {msg.metrics.count && (
                        <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                          {msg.metrics.count} boleto(s)
                        </span>
                      )}
                    </div>
                  )}

                  {/* Shortcut action button */}
                  {msg.action && (
                    <button
                      className="btn-secondary"
                      onClick={() => navigate(msg.action!.route)}
                      style={{
                        fontSize: 12, padding: '6px 12px',
                        justifyContent: 'space-between',
                        alignSelf: 'flex-start',
                      }}
                    >
                      <span>{msg.action.label}</span>
                      <ArrowRight size={14} style={{ marginLeft: 6 }} />
                    </button>
                  )}
                </div>
              </div>
            );
          })}

          {/* Typing indicator */}
          {loading && (
            <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
              <div style={{
                width: 32, height: 32, borderRadius: 'var(--radius-full)',
                background: 'var(--brand-dim)', display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>
                <Bot size={18} color="var(--brand)" />
              </div>
              <div style={{
                padding: '10px 14px', borderRadius: '4px 16px 16px 16px',
                background: 'var(--surface)', border: '1px solid var(--border)',
                display: 'flex', gap: 6, alignItems: 'center',
              }}>
                <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s infinite alternate' }} />
                <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s 0.2s infinite alternate' }} />
                <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s 0.4s infinite alternate' }} />
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Suggested Quick Prompt Chips */}
      <div style={{
        flexShrink: 0,
        overflowX: 'auto',
        whiteSpace: 'nowrap',
        padding: '8px 16px',
        borderTop: '1px solid var(--border)',
        background: 'var(--surface)',
      }}>
        <div className="container" style={{ display: 'flex', gap: 8, padding: 0 }}>
          {promptSuggestions.map((prompt, i) => (
            <button
              key={i}
              onClick={() => handleSend(prompt)}
              className="btn-ghost"
              style={{
                fontSize: 12,
                padding: '6px 12px',
                borderRadius: 999,
                background: 'var(--surface-2)',
                border: '1px solid var(--border)',
                whiteSpace: 'nowrap',
                flexShrink: 0,
                color: 'var(--text)',
              }}
            >
              {prompt}
            </button>
          ))}
        </div>
      </div>

      {/* Message Input Box */}
      <div style={{
        flexShrink: 0,
        padding: '12px 16px',
        background: 'var(--surface)',
        borderTop: '1px solid var(--border)',
      }}>
        <div className="container" style={{ padding: 0, display: 'flex', gap: 8 }}>
          <input
            type="text"
            className="input"
            placeholder="Pergunte ao assistente (ex: 'O que vence hoje?')..."
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') handleSend();
            }}
            disabled={loading}
            style={{ borderRadius: 'var(--radius-full)' }}
          />
          <button
            className="btn-primary btn-icon"
            onClick={() => handleSend()}
            disabled={!input.trim() || loading}
            aria-label="Enviar mensagem"
            style={{ width: 44, height: 44, borderRadius: 'var(--radius-full)', flexShrink: 0 }}
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </main>
  );
}
