import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Bell, ArrowLeft, MessageSquare, Mail, Smartphone,
  Clock, Save,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { NotificationPref } from '../types/database';

const DEFAULT_PREFS: Omit<NotificationPref, 'user_id' | 'org_id'> = {
  push: true,
  whatsapp: false,
  email: false,
  whatsapp_number: null,
  days_before: [7, 2, 0],
  send_hour: 9,
};

const DAYS_OPTIONS = [
  { value: 0, label: 'No dia' },
  { value: 1, label: '1 dia antes' },
  { value: 2, label: '2 dias antes' },
  { value: 3, label: '3 dias antes' },
  { value: 7, label: '7 dias antes' },
  { value: 14, label: '14 dias antes' },
];

function useNotifPrefs(userId: string | undefined, orgId: string | undefined) {
  return useQuery({
    queryKey: ['notification_prefs', userId, orgId],
    queryFn: async () => {
      if (!userId || !orgId) return null;
      const { data } = await supabase
        .from('notification_prefs')
        .select('*')
        .eq('user_id', userId)
        .eq('org_id', orgId)
        .maybeSingle();
      return data as NotificationPref | null;
    },
    enabled: !!userId && !!orgId,
  });
}

function Toggle({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      style={{
        width: 48, height: 28, borderRadius: 999,
        background: checked ? 'var(--brand)' : 'var(--surface-2)',
        border: checked ? 'none' : '2px solid var(--border)',
        cursor: 'pointer', transition: 'background 0.2s',
        position: 'relative', flexShrink: 0,
      }}
    >
      <div style={{
        width: 20, height: 20, borderRadius: '50%',
        background: checked ? 'var(--on-brand)' : 'var(--text-muted)',
        position: 'absolute', top: 4,
        left: checked ? 24 : 4,
        transition: 'left 0.2s',
      }} />
    </button>
  );
}

export default function NotificationsPage() {
  const { user, currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: prefs, isLoading } = useNotifPrefs(user?.id, currentOrg?.org_id);

  const [push, setPush] = useState(prefs?.push ?? DEFAULT_PREFS.push);
  const [whatsapp, setWhatsapp] = useState(prefs?.whatsapp ?? DEFAULT_PREFS.whatsapp);
  const [email, setEmail] = useState(prefs?.email ?? DEFAULT_PREFS.email);
  const [whatsappNumber, setWhatsappNumber] = useState(prefs?.whatsapp_number ?? '');
  const [daysBefore, setDaysBefore] = useState<number[]>(prefs?.days_before ?? DEFAULT_PREFS.days_before);
  const [sendHour, setSendHour] = useState(prefs?.send_hour ?? DEFAULT_PREFS.send_hour);

  // Sync with loaded prefs
  const [synced, setSynced] = useState(false);
  if (prefs && !synced) {
    setPush(prefs.push);
    setWhatsapp(prefs.whatsapp);
    setEmail(prefs.email);
    setWhatsappNumber(prefs.whatsapp_number ?? '');
    setDaysBefore(prefs.days_before ?? [7, 2, 0]);
    setSendHour(prefs.send_hour ?? 9);
    setSynced(true);
  }

  const saveMutation = useMutation({
    mutationFn: async () => {
      if (!user?.id || !currentOrg?.org_id) throw new Error('Sem sessão');
      const payload = {
        user_id: user.id,
        org_id: currentOrg.org_id,
        push,
        whatsapp,
        email,
        whatsapp_number: whatsappNumber || null,
        days_before: daysBefore.sort((a, b) => b - a),
        send_hour: sendHour,
      };
      const { error } = await supabase
        .from('notification_prefs')
        .upsert(payload, { onConflict: 'user_id,org_id' });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notification_prefs'] });
      toast('Preferências salvas!', 'success');
    },
    onError: () => toast('Erro ao salvar preferências.', 'error'),
  });

  function toggleDay(day: number) {
    setDaysBefore(prev =>
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  }

  return (
    <main className="page" id="page-notifications">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Notificações</h1>
        </div>
      </header>

      <div className="page-content container">
        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(3)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 72, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
            {/* Channels section */}
            <section className="card" aria-labelledby="channels-heading">
              <h2 id="channels-heading" style={{ fontSize: 'var(--text-sm)', fontWeight: 700, marginBottom: 'var(--space-4)', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                Canais de envio
              </h2>

              {/* Push */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', paddingBottom: 'var(--space-4)', borderBottom: '1px solid var(--border)' }}>
                <div style={{ width: 40, height: 40, borderRadius: 'var(--radius-md)', background: 'var(--brand-dim)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <Smartphone size={18} color="var(--brand)" />
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>Push (notificação no celular)</p>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Requer app instalado na tela inicial</p>
                </div>
                <Toggle checked={push} onChange={setPush} label="Ativar push" />
              </div>

              {/* WhatsApp */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', paddingTop: 'var(--space-4)', paddingBottom: 'var(--space-4)', borderBottom: '1px solid var(--border)' }}>
                <div style={{ width: 40, height: 40, borderRadius: 'var(--radius-md)', background: 'rgba(37, 211, 102, 0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <MessageSquare size={18} color="#25D366" />
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>WhatsApp</p>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Via API oficial da Meta · Requer opt-in</p>
                </div>
                <Toggle checked={whatsapp} onChange={setWhatsapp} label="Ativar WhatsApp" />
              </div>

              {whatsapp && (
                <div className="input-group" style={{ paddingTop: 'var(--space-3)' }}>
                  <label htmlFor="whatsapp-number" className="input-label">Número WhatsApp</label>
                  <input
                    id="whatsapp-number"
                    type="tel"
                    className="input"
                    placeholder="+55 51 9 9999-9999"
                    value={whatsappNumber}
                    onChange={e => setWhatsappNumber(e.target.value)}
                  />
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', marginTop: 4 }}>
                    Ao salvar, você confirma o opt-in para receber alertas de boletos por WhatsApp.
                  </p>
                </div>
              )}

              {/* Email */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', paddingTop: 'var(--space-4)' }}>
                <div style={{ width: 40, height: 40, borderRadius: 'var(--radius-md)', background: 'rgba(96, 165, 250, 0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <Mail size={18} color="#60A5FA" />
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>E-mail</p>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Enviado para {user?.email}</p>
                </div>
                <Toggle checked={email} onChange={setEmail} label="Ativar e-mail" />
              </div>
            </section>

            {/* Timing section */}
            <section className="card" aria-labelledby="timing-heading">
              <h2 id="timing-heading" style={{ fontSize: 'var(--text-sm)', fontWeight: 700, marginBottom: 'var(--space-4)', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                Quando avisar
              </h2>

              <div className="input-group" style={{ marginBottom: 'var(--space-4)' }}>
                <label className="input-label">Antecedência dos alertas</label>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginBottom: 'var(--space-3)' }}>
                  Selecione quando deseja ser avisado antes do vencimento.
                </p>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--space-2)' }}>
                  {DAYS_OPTIONS.map(opt => (
                    <button
                      key={opt.value}
                      onClick={() => toggleDay(opt.value)}
                      className={`chip ${daysBefore.includes(opt.value) ? 'chip-brand' : 'chip-neutral'}`}
                      style={{ cursor: 'pointer', border: 'none' }}
                      aria-pressed={daysBefore.includes(opt.value)}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              <div className="input-group">
                <label htmlFor="send-hour" className="input-label" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                  <Clock size={14} /> Horário de envio
                </label>
                <select
                  id="send-hour"
                  className="input"
                  value={sendHour}
                  onChange={e => setSendHour(parseInt(e.target.value))}
                >
                  {Array.from({ length: 24 }, (_, h) => (
                    <option key={h} value={h}>
                      {String(h).padStart(2, '0')}:00 (Brasília)
                    </option>
                  ))}
                </select>
              </div>
            </section>

            {/* Info box */}
            <div style={{
              padding: 'var(--space-4)',
              background: 'var(--surface-2)',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border)',
            }}>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.6 }}>
                <Bell size={12} style={{ display: 'inline', marginRight: 4 }} aria-hidden="true" />
                Boletos atrasados geram avisos diários por até 7 dias, depois semanalmente, para evitar sobrecarga de notificações.
              </p>
            </div>

            {/* Save */}
            <button
              id="btn-save-notif-prefs"
              className="btn btn-primary btn-full btn-lg"
              onClick={() => saveMutation.mutate()}
              disabled={saveMutation.isPending}
              aria-busy={saveMutation.isPending}
            >
              <Save size={18} aria-hidden="true" />
              {saveMutation.isPending ? 'Salvando...' : 'Salvar preferências'}
            </button>
          </div>
        )}
      </div>
    </main>
  );
}
