// PWA helper functions and service worker management

declare global {
  interface Window {
    __pwaInstallPrompt?: any;
  }
}

export function registerServiceWorker() {
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      const swUrl = `${import.meta.env.BASE_URL}sw.js`;
      navigator.serviceWorker
        .register(swUrl, { scope: import.meta.env.BASE_URL })
        .then((reg) => {
          console.log('[PWA] Service Worker registered successfully with scope:', reg.scope);
        })
        .catch((err) => {
          console.warn('[PWA] Service Worker registration failed:', err);
        });
    });
  }
}

export function getInstallPrompt(): any {
  if (typeof window !== 'undefined') {
    return window.__pwaInstallPrompt ?? null;
  }
  return null;
}

export async function promptPwaInstall(): Promise<boolean> {
  const promptEvent = getInstallPrompt();
  if (!promptEvent) return false;

  try {
    promptEvent.prompt();
    const choice = await promptEvent.userChoice;
    if (choice?.outcome === 'accepted') {
      window.__pwaInstallPrompt = null;
      return true;
    }
    return false;
  } catch (err) {
    console.error('[PWA] Error showing install prompt:', err);
    return false;
  }
}
