import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import { validateBarcodeLine } from '../lib/utils';
import { ArrowLeft, Save, AlertCircle, Trash2 } from 'lucide-react';
import type { Supplier, Category, BillView } from '../types/database';

function useBill(id: string | undefined, orgId: string | undefined) {
  return useQuery({
    queryKey: ['bill', id],
    queryFn: async () => {
      if (!id || !orgId) throw new Error('No id or org');
      const { data, error } = await supabase
        .from('bills_view')
        .select('*')
        .eq('id', id)
        .eq('org_id', orgId)
        .single();
      if (error) throw error;
      return data as BillView;
    },
    enabled: !!id && !!orgId,
  });
}

function useSuppliers(orgId: string | undefined) {
  return useQuery({
    queryKey: ['suppliers', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data } = await supabase
        .from('suppliers')
        .select('*')
        .eq('org_id', orgId)
        .order('name');
      return (data ?? []) as Supplier[];
    },
    enabled: !!orgId,
  });
}

function useCategories(orgId: string | undefined) {
  return useQuery({
    queryKey: ['categories', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data } = await supabase
        .from('categories')
        .select('*')
        .eq('org_id', orgId)
        .order('name');
      return (data ?? []) as Category[];
    },
    enabled: !!orgId,
  });
}

interface EditBillFormProps {
  bill: BillView;
  id: string;
  orgId: string;
  suppliers: Supplier[];
  categories: Category[];
}

function EditBillForm({ bill, id, orgId, suppliers, categories }: EditBillFormProps) {
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [form, setForm] = useState({
    beneficiary_name: bill.beneficiary_name ?? '',
    description: bill.description ?? '',
    amount: String(bill.amount),
    due_date: bill.due_date,
    barcode_line: bill.barcode_line ?? '',
    supplier_id: bill.supplier_id ?? '',
    category_id: bill.category_id ?? '',
  });

  const [saving, setSaving] = useState(false);
  const [showCancel, setShowCancel] = useState(false);
  const [barcodeError, setBarcodeError] = useState('');

  const cancelMutation = useMutation({
    mutationFn: async () => {
      const { error } = await supabase
        .from('bills')
        .update({ status: 'canceled' })
        .eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bills'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      toast('Boleto cancelado.', 'success');
      navigate('/boletos');
    },
    onError: () => toast('Erro ao cancelar o boleto.', 'error'),
  });

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    // Barcode validation
    if (form.barcode_line && !validateBarcodeLine(form.barcode_line)) {
      setBarcodeError('Linha digitável inválida (deve ter 47 ou 48 dígitos)');
      return;
    }
    setBarcodeError('');

    // Duplicate barcode check (excluding this bill)
    if (form.barcode_line) {
      const cleaned = form.barcode_line.replace(/\D/g, '');
      const { data: existing } = await supabase
        .from('bills')
        .select('id')
        .eq('org_id', orgId)
        .eq('barcode_line', cleaned)
        .neq('status', 'canceled')
        .neq('id', id)
        .maybeSingle();

      if (existing) {
        toast('Já existe outro boleto com essa linha digitável.', 'error');
        return;
      }
    }

    setSaving(true);
    const { error } = await supabase
      .from('bills')
      .update({
        beneficiary_name: form.beneficiary_name || null,
        description: form.description || null,
        amount: parseFloat(form.amount.replace(',', '.')),
        due_date: form.due_date,
        barcode_line: form.barcode_line ? form.barcode_line.replace(/\D/g, '') : null,
        supplier_id: form.supplier_id || null,
        category_id: form.category_id || null,
      })
      .eq('id', id);

    setSaving(false);

    if (error) {
      toast('Erro ao salvar o boleto.', 'error');
      return;
    }

    queryClient.invalidateQueries({ queryKey: ['bill', id] });
    queryClient.invalidateQueries({ queryKey: ['bills'] });
    queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    toast('Boleto atualizado com sucesso!', 'success');
    navigate(`/boletos/${id}`);
  }

  return (
    <main className="page" id="page-edit-bill">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button
            className="btn-ghost btn-icon"
            onClick={() => navigate(-1)}
            aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}
          >
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Editar boleto</h1>
          {bill.status === 'pending' && (
            <button
              className="btn-ghost btn-icon"
              onClick={() => setShowCancel(true)}
              aria-label="Cancelar boleto"
              style={{ color: 'var(--urgent)', width: 40, height: 40, minHeight: 40 }}
            >
              <Trash2 size={18} />
            </button>
          )}
        </div>
      </header>

      <div className="page-content container">
        <form onSubmit={handleSubmit} noValidate>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
            {/* Beneficiary */}
            <div className="input-group">
              <label htmlFor="edit-beneficiary" className="input-label">Beneficiário</label>
              <input
                id="edit-beneficiary"
                type="text"
                className="input"
                placeholder="Ex: Casio do Brasil"
                value={form.beneficiary_name}
                onChange={e => setForm(f => ({ ...f, beneficiary_name: e.target.value }))}
              />
            </div>

            {/* Description */}
            <div className="input-group">
              <label htmlFor="edit-description" className="input-label">Descrição</label>
              <input
                id="edit-description"
                type="text"
                className="input"
                placeholder="Ex: Reposição relógios linha Vintage"
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
              />
            </div>

            {/* Amount + Due date */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>
              <div className="input-group">
                <label htmlFor="edit-amount" className="input-label">Valor (R$) *</label>
                <input
                  id="edit-amount"
                  type="number"
                  step="0.01"
                  min="0.01"
                  required
                  className="input amount"
                  placeholder="0,00"
                  value={form.amount}
                  onChange={e => setForm(f => ({ ...f, amount: e.target.value }))}
                />
              </div>

              <div className="input-group">
                <label htmlFor="edit-due-date" className="input-label">Vencimento *</label>
                <input
                  id="edit-due-date"
                  type="date"
                  required
                  className="input"
                  value={form.due_date}
                  onChange={e => setForm(f => ({ ...f, due_date: e.target.value }))}
                />
              </div>
            </div>

            {/* Barcode */}
            <div className="input-group">
              <label htmlFor="edit-barcode" className="input-label">Linha digitável</label>
              <input
                id="edit-barcode"
                type="text"
                className={`input ${barcodeError ? 'input-error' : ''}`}
                placeholder="Cole aqui os 47 ou 48 dígitos"
                value={form.barcode_line}
                onChange={e => {
                  setBarcodeError('');
                  setForm(f => ({ ...f, barcode_line: e.target.value }));
                }}
              />
              {barcodeError && (
                <span className="input-error-msg" role="alert">
                  <AlertCircle size={12} style={{ display: 'inline', marginRight: 4 }} />
                  {barcodeError}
                </span>
              )}
            </div>

            {/* Supplier */}
            {suppliers.length > 0 && (
              <div className="input-group">
                <label htmlFor="edit-supplier" className="input-label">Fornecedor</label>
                <select
                  id="edit-supplier"
                  className="input"
                  value={form.supplier_id}
                  onChange={e => setForm(f => ({ ...f, supplier_id: e.target.value }))}
                >
                  <option value="">Nenhum</option>
                  {suppliers.map(s => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>
              </div>
            )}

            {/* Category */}
            {categories.length > 0 && (
              <div className="input-group">
                <label htmlFor="edit-category" className="input-label">Categoria</label>
                <select
                  id="edit-category"
                  className="input"
                  value={form.category_id}
                  onChange={e => setForm(f => ({ ...f, category_id: e.target.value }))}
                >
                  <option value="">Nenhuma</option>
                  {categories.map(c => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>
            )}

            {/* Submit */}
            <button
              type="submit"
              className="btn btn-primary"
              disabled={saving}
              style={{ width: '100%', marginTop: 'var(--space-2)' }}
            >
              <Save size={18} />
              <span>{saving ? 'Salvando...' : 'Salvar alterações'}</span>
            </button>
          </div>
        </form>

        {/* Cancel modal */}
        {showCancel && (
          <div
            style={{
              position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)',
              backdropFilter: 'blur(4px)', zIndex: 100,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              padding: 'var(--space-4)',
            }}
            role="dialog"
            aria-modal="true"
            aria-labelledby="cancel-title"
          >
            <div className="card" style={{ maxWidth: 360, width: '100%' }}>
              <h2 id="cancel-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700, marginBottom: 'var(--space-2)' }}>
                Cancelar boleto?
              </h2>
              <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', marginBottom: 'var(--space-6)' }}>
                O boleto sairá das pendências e não gerará mais alertas.
              </p>
              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button
                  className="btn btn-secondary"
                  style={{ flex: 1 }}
                  onClick={() => setShowCancel(false)}
                >
                  Voltar
                </button>
                <button
                  className="btn btn-danger"
                  style={{ flex: 1 }}
                  disabled={cancelMutation.isPending}
                  onClick={() => cancelMutation.mutate()}
                >
                  {cancelMutation.isPending ? 'Cancelando...' : 'Sim, cancelar'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </main>
  );
}

export default function EditBillPage() {
  const { id } = useParams<{ id: string }>();
  const { currentOrg } = useAuth();
  const navigate = useNavigate();

  const { data: bill, isLoading: loadingBill } = useBill(id, currentOrg?.org_id);
  const { data: suppliers = [] } = useSuppliers(currentOrg?.org_id);
  const { data: categories = [] } = useCategories(currentOrg?.org_id);

  if (loadingBill) {
    return (
      <main className="page">
        <div className="page-content container">
          <div className="skeleton" style={{ height: 400, borderRadius: 'var(--radius-lg)' }} />
        </div>
      </main>
    );
  }

  if (!bill || !currentOrg) {
    return (
      <main className="page">
        <div className="page-content container">
          <div className="empty-state">
            <AlertCircle size={48} color="var(--urgent)" />
            <h2>Boleto não encontrado</h2>
            <button className="btn btn-secondary" onClick={() => navigate('/boletos')}>Voltar</button>
          </div>
        </div>
      </main>
    );
  }

  return (
    <EditBillForm
      bill={bill}
      id={id!}
      orgId={currentOrg.org_id}
      suppliers={suppliers}
      categories={categories}
    />
  );
}
