import type { BillView } from '../types/database';
import {
  formatCurrency,
  getDueDateLabel,
  URGENCY_CSS_CLASS,
  URGENCY_LABELS,
  getUrgency,
} from '../lib/utils';
import { Copy, CheckCircle2, Clock, AlertTriangle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useToast } from './Toast';

interface BillCardProps {
  bill: BillView;
}

export function BillCard({ bill }: BillCardProps) {
  const navigate = useNavigate();
  const { toast } = useToast();
  const urgency = bill.urgency ?? getUrgency(bill.due_date, bill.status);
  const chipClass = URGENCY_CSS_CLASS[urgency];
  const dueDateLabel = getDueDateLabel(bill.due_date, bill.status);

  const UrgencyIcon = urgency === 'urgent'
    ? AlertTriangle
    : urgency === 'soon'
      ? Clock
      : CheckCircle2;

  async function copyBarcode(e: React.MouseEvent) {
    e.stopPropagation();
    if (!bill.barcode_line) return;
    await navigator.clipboard.writeText(bill.barcode_line);
    toast('Código de barras copiado!', 'success');
  }

  return (
    <div
      className="bill-item animate-fade-in"
      onClick={() => navigate(`/boletos/${bill.id}`)}
      role="button"
      tabIndex={0}
      onKeyDown={e => e.key === 'Enter' && navigate(`/boletos/${bill.id}`)}
      aria-label={`Boleto ${bill.beneficiary_name ?? bill.description}, ${formatCurrency(bill.amount)}`}
    >
      {/* Urgency indicator */}
      <div
        className="bill-item-icon"
        style={{ background: urgency === 'paid' ? 'var(--paid-bg)' : `var(--${urgency === 'urgent' ? 'urgent' : urgency === 'soon' ? 'soon' : 'ok'}-bg)` }}
        aria-hidden="true"
      >
        <UrgencyIcon
          size={22}
          color={urgency === 'urgent' ? 'var(--urgent)' : urgency === 'soon' ? 'var(--soon)' : urgency === 'ok' ? 'var(--ok)' : 'var(--paid)'}
        />
      </div>

      {/* Content */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 2 }}>
          <p style={{
            fontSize: 'var(--text-sm)',
            fontWeight: 600,
            color: 'var(--text)',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            flex: 1,
          }}>
            {bill.beneficiary_name ?? bill.description ?? 'Boleto sem nome'}
          </p>
          <span className={`chip ${chipClass}`} aria-label={`Urgência: ${URGENCY_LABELS[urgency]}`}>
            {URGENCY_LABELS[urgency]}
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
            {dueDateLabel}
            {bill.supplier_name && ` · ${bill.supplier_name}`}
          </p>
          <p className="amount" style={{
            fontSize: 'var(--text-sm)',
            fontWeight: 700,
            color: bill.status === 'paid' ? 'var(--paid)' : 'var(--text)',
          }}>
            {formatCurrency(bill.amount)}
          </p>
        </div>
      </div>

      {/* Copy barcode button */}
      {bill.barcode_line && bill.status === 'pending' && (
        <button
          className="btn-ghost btn-icon btn-sm"
          onClick={copyBarcode}
          aria-label="Copiar código de barras"
          style={{ flexShrink: 0, marginLeft: 'var(--space-1)' }}
        >
          <Copy size={16} />
        </button>
      )}
    </div>
  );
}
