import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Camera, FlipHorizontal, Flashlight, Sparkles } from 'lucide-react';
import { extractBoletoData } from '../../lib/utils';
import { useToast } from '../../components/Toast';

export default function ScanBillPage() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const [hasCamera, setHasCamera] = useState<boolean | null>(null);
  const [torchOn, setTorchOn] = useState(false);
  const [facingMode, setFacingMode] = useState<'environment' | 'user'>('environment');
  const [analyzing, setAnalyzing] = useState(false);
  const [manualInput, setManualInput] = useState('');

  // Start camera
  useEffect(() => {
    let isMounted = true;

    async function startCamera() {
      try {
        if (!navigator.mediaDevices?.getUserMedia) {
          if (isMounted) setHasCamera(false);
          return;
        }

        // Stop any existing stream
        if (streamRef.current) {
          streamRef.current.getTracks().forEach(track => track.stop());
        }

        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode,
            width: { ideal: 1280 },
            height: { ideal: 720 },
          },
        });

        if (!isMounted) {
          stream.getTracks().forEach(t => t.stop());
          return;
        }

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => {});
        }
        setHasCamera(true);
      } catch (err) {
        console.warn('Camera error or permission denied:', err);
        if (isMounted) setHasCamera(false);
      }
    }

    startCamera();

    return () => {
      isMounted = false;
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [facingMode]);

  // Torch / Flashlight toggle
  async function toggleTorch() {
    if (!streamRef.current) return;
    const track = streamRef.current.getVideoTracks()[0];
    if (!track) return;

    try {
      const capabilities = track.getCapabilities?.() as any;
      if (capabilities?.torch) {
        await track.applyConstraints({
          advanced: [{ torch: !torchOn } as any],
        });
        setTorchOn(!torchOn);
      } else {
        toast('Flash não suportado neste dispositivo.', 'info');
      }
    } catch {
      toast('Não foi possível alternar o flash.', 'error');
    }
  }

  // Handle scanned or typed line
  function handleProcessCode(code: string, sourceName?: string) {
    const cleaned = code.replace(/\D/g, '');
    if (cleaned.length < 44) {
      toast('Código de barras incompleto. Digite ou aponte para um código válido.', 'error');
      return;
    }

    const parsed = extractBoletoData(cleaned);

    toast(
      parsed
        ? `Código reconhecido! Vencimento: ${parsed.dueDate || 'A definir'}, Valor: ${parsed.amount ? 'R$ ' + parsed.amount.toFixed(2) : 'A definir'}`
        : 'Código capturado. Avance para revisão.',
      'success'
    );

    // Redirect to mandatory review in ManualBillPage
    setTimeout(() => {
      navigate('/adicionar/manual', {
        state: {
          prefill: {
            barcode_line: cleaned,
            amount: parsed?.amount ? String(parsed.amount) : '',
            due_date: parsed?.dueDate || '',
            beneficiary_name: parsed?.bankName || (sourceName ?? 'Beneficiário a revisar'),
            description: `Leitura por código de barras`,
          },
        },
      });
    }, 900);
  }

  // Test barcode presets for quick review
  function simulateSample(bank: 'casio' | 'seiko' | 'tributo') {
    setAnalyzing(true);
    setTimeout(() => {
      setAnalyzing(false);
      if (bank === 'casio') {
        // Standard boleto (Casio)
        handleProcessCode('34191790010104351004791020150008499990000345000', 'Casio Relógios Brasil');
      } else if (bank === 'seiko') {
        // Seiko boleto
        handleProcessCode('00190000090123456789123456789012399990000125000', 'Seiko Distribuidora');
      } else {
        // Concessionaria 48 digitos
        handleProcessCode('846700000013456700850020123456789012345678901234', 'CEEE Equatorial Energia');
      }
    }, 600);
  }

  return (
    <main className="page" id="page-scan-bill" style={{ background: '#000000' }}>
      <header className="page-header" style={{ background: 'rgba(11, 13, 18, 0.85)', backdropFilter: 'blur(12px)' }}>
        <div className="container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <button
              className="btn-ghost btn-icon"
              onClick={() => navigate(-1)}
              aria-label="Voltar"
              style={{ width: 40, height: 40, minHeight: 40 }}
            >
              <ArrowLeft size={20} />
            </button>
            <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700 }}>Escanear boleto</h1>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {hasCamera && (
              <>
                <button
                  className="btn-ghost btn-icon"
                  onClick={toggleTorch}
                  title="Flash"
                  aria-label="Alternar flash"
                  style={{ color: torchOn ? 'var(--brand)' : 'var(--text)' }}
                >
                  <Flashlight size={20} />
                </button>
                <button
                  className="btn-ghost btn-icon"
                  onClick={() => setFacingMode(prev => prev === 'environment' ? 'user' : 'environment')}
                  title="Alternar câmera"
                  aria-label="Alternar câmera"
                >
                  <FlipHorizontal size={20} />
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      <div className="page-content container" style={{ padding: '0 16px', display: 'flex', flexDirection: 'column', gap: 16 }}>
        {/* Viewfinder area */}
        <div style={{
          position: 'relative',
          width: '100%',
          height: 340,
          borderRadius: 'var(--radius-xl)',
          overflow: 'hidden',
          background: '#0d1117',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          boxShadow: '0 8px 32px rgba(0,0,0,0.7)',
          border: '1px solid var(--border)',
        }}>
          {hasCamera ? (
            <video
              ref={videoRef}
              playsInline
              muted
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            />
          ) : (
            <div style={{ textAlign: 'center', padding: 24, maxWidth: 300 }}>
              <Camera size={44} color="var(--text-muted)" style={{ margin: '0 auto 12px' }} />
              <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', color: '#fff', marginBottom: 4 }}>
                Câmera indisponível ou permissão negada
              </p>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginBottom: 16 }}>
                Você pode colar a linha digitável abaixo ou testar com um modelo rápido de demonstração.
              </p>
            </div>
          )}

          {/* Viewfinder laser and brackets */}
          <div style={{
            position: 'absolute',
            inset: '30px 20px',
            border: '2px dashed rgba(255, 242, 26, 0.45)',
            borderRadius: 'var(--radius-lg)',
            pointerEvents: 'none',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: 12,
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
              <div style={{ width: 16, height: 16, borderTop: '3px solid var(--brand)', borderLeft: '3px solid var(--brand)' }} />
              <div style={{ width: 16, height: 16, borderTop: '3px solid var(--brand)', borderRight: '3px solid var(--brand)' }} />
            </div>

            {/* Scanning line animation */}
            <div style={{
              width: '90%',
              height: 2,
              background: 'linear-gradient(90deg, transparent, var(--brand), transparent)',
              boxShadow: '0 0 12px var(--brand)',
              animation: 'scanLaser 2s infinite ease-in-out',
            }} />

            <div style={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
              <div style={{ width: 16, height: 16, borderBottom: '3px solid var(--brand)', borderLeft: '3px solid var(--brand)' }} />
              <div style={{ width: 16, height: 16, borderBottom: '3px solid var(--brand)', borderRight: '3px solid var(--brand)' }} />
            </div>
          </div>

          <style>{`
            @keyframes scanLaser {
              0% { transform: translateY(-70px); opacity: 0.3; }
              50% { transform: translateY(70px); opacity: 1; }
              100% { transform: translateY(-70px); opacity: 0.3; }
            }
          `}</style>
        </div>

        {/* Tip text */}
        <p style={{
          textAlign: 'center',
          fontSize: 'var(--text-xs)',
          color: 'var(--text-muted)',
          margin: '0 auto',
          maxWidth: 320,
        }}>
          Enquadre o código de barras ou a linha digitável na horizontal dentro da área pontilhada.
        </p>

        {/* Manual paste input */}
        <div className="card" style={{ padding: 'var(--space-4)', background: 'var(--surface)' }}>
          <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: '#fff', marginBottom: 8 }}>
            Ou cole a linha digitável (47 ou 48 dígitos)
          </p>
          <div style={{ display: 'flex', gap: 8 }}>
            <input
              type="text"
              className="input"
              placeholder="34191.79001 01043.510047..."
              value={manualInput}
              onChange={e => setManualInput(e.target.value)}
              style={{ flex: 1, fontFamily: 'monospace', fontSize: 13 }}
            />
            <button
              className="btn-primary"
              style={{ padding: '0 16px', minWidth: 90 }}
              disabled={!manualInput.trim()}
              onClick={() => handleProcessCode(manualInput, 'Boleto Inserido')}
            >
              Ler
            </button>
          </div>
        </div>

        {/* Fast simulation shortcuts for Morpheus testing */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 4 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'var(--brand)', fontSize: 'var(--text-xs)', fontWeight: 600 }}>
            <Sparkles size={14} />
            <span>Simulações instantâneas de leitura (Ambiente Morpheus)</span>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 8 }}>
            <button
              className="btn-secondary"
              style={{ fontSize: 12, padding: '8px 12px', justifyContent: 'flex-start', textAlign: 'left' }}
              disabled={analyzing}
              onClick={() => simulateSample('casio')}
            >
              ⌚ Casio · R$ 345,00
            </button>
            <button
              className="btn-secondary"
              style={{ fontSize: 12, padding: '8px 12px', justifyContent: 'flex-start', textAlign: 'left' }}
              disabled={analyzing}
              onClick={() => simulateSample('seiko')}
            >
              ⏱️ Seiko · R$ 1.250,00
            </button>
            <button
              className="btn-secondary"
              style={{ fontSize: 12, padding: '8px 12px', justifyContent: 'flex-start', textAlign: 'left' }}
              disabled={analyzing}
              onClick={() => simulateSample('tributo')}
            >
              ⚡ Energia · Concessionária
            </button>
          </div>
        </div>
      </div>
    </main>
  );
}
