import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import {
  LayoutDashboard,
  FileText,
  Plus,
  MessageSquare,
  Building2,
  Settings,
  LogOut,
  Clock,
  Sparkles,
} from 'lucide-react';

export function Sidebar() {
  const { user, currentOrg, signOut } = useAuth();
  const navigate = useNavigate();

  const userInitials =
    user?.user_metadata?.full_name
      ? user.user_metadata.full_name
          .split(' ')
          .map((n: string) => n[0])
          .slice(0, 2)
          .join('')
          .toUpperCase()
      : user?.email?.[0]?.toUpperCase() ?? 'M';

  const roleLabel =
    currentOrg?.role === 'owner'
      ? 'Proprietário'
      : currentOrg?.role === 'finance'
      ? 'Financeiro'
      : 'Visualizador';

  return (
    <aside className="sidebar" aria-label="Menu principal">
      {/* Brand Header */}
      <div className="sidebar-brand">
        <div className="sidebar-logo-icon">
          <Clock size={22} strokeWidth={2.5} color="var(--on-brand)" />
        </div>
        <div className="sidebar-brand-text">
          <div className="sidebar-brand-title">
            <span>CRONOS</span>
            <span className="sidebar-brand-badge">PRO</span>
          </div>
          <span className="sidebar-brand-sub">
            {currentOrg?.organization?.name || 'Morpheus Relojoaria'}
          </span>
        </div>
      </div>

      {/* Primary Action Button */}
      <div className="sidebar-cta">
        <button
          id="sidebar-btn-add"
          className="btn btn-primary btn-full"
          onClick={() => navigate('/adicionar')}
          aria-label="Adicionar novo boleto"
        >
          <Plus size={18} strokeWidth={2.5} />
          <span>Novo boleto</span>
        </button>
      </div>

      {/* Nav Links */}
      <nav className="sidebar-nav">
        <div className="sidebar-nav-group-title">MENU PRINCIPAL</div>
        <NavLink
          to="/"
          end
          className={({ isActive }) => `sidebar-nav-item ${isActive ? 'active' : ''}`}
          id="sidebar-nav-home"
        >
          <LayoutDashboard size={20} className="sidebar-nav-icon" />
          <span>Início</span>
        </NavLink>

        <NavLink
          to="/boletos"
          className={({ isActive }) => `sidebar-nav-item ${isActive ? 'active' : ''}`}
          id="sidebar-nav-bills"
        >
          <FileText size={20} className="sidebar-nav-icon" />
          <span>Boletos</span>
        </NavLink>

        <NavLink
          to="/assistente"
          className={({ isActive }) => `sidebar-nav-item ${isActive ? 'active' : ''}`}
          id="sidebar-nav-assistant"
        >
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
            <MessageSquare size={20} className="sidebar-nav-icon" />
            <Sparkles
              size={10}
              color="var(--brand)"
              style={{ position: 'absolute', top: -3, right: -4 }}
            />
          </div>
          <span>Assistente IA</span>
          <span className="sidebar-pill-new">FASE 3</span>
        </NavLink>

        <div className="sidebar-nav-group-title" style={{ marginTop: 'var(--space-4)' }}>
          GESTÃO
        </div>

        <NavLink
          to="/fornecedores"
          className={({ isActive }) => `sidebar-nav-item ${isActive ? 'active' : ''}`}
          id="sidebar-nav-suppliers"
        >
          <Building2 size={20} className="sidebar-nav-icon" />
          <span>Fornecedores</span>
        </NavLink>

        <NavLink
          to="/mais"
          className={({ isActive }) => `sidebar-nav-item ${isActive ? 'active' : ''}`}
          id="sidebar-nav-settings"
        >
          <Settings size={20} className="sidebar-nav-icon" />
          <span>Configurações</span>
        </NavLink>
      </nav>

      {/* Bottom Profile section */}
      <div className="sidebar-footer">
        <div className="sidebar-user-card" onClick={() => navigate('/mais')} role="button" tabIndex={0}>
          <div className="sidebar-user-avatar">
            {userInitials}
          </div>
          <div className="sidebar-user-info">
            <span className="sidebar-user-name">
              {user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Usuário'}
            </span>
            <span className="sidebar-user-role">{roleLabel}</span>
          </div>
        </div>
        <button
          className="btn-ghost btn-icon sidebar-logout-btn"
          onClick={() => signOut()}
          aria-label="Sair da conta"
          title="Sair"
        >
          <LogOut size={18} />
        </button>
      </div>
    </aside>
  );
}
